import type { BChap } from '../types';
const C: BChap[] = [{"v":["Оскільки багато хто почав складати оповіді про добре відомі нам речі,","як передали нам ті, що від самого початку були очевидцями і служителями Слова*,","то спало на думку й мені, старанно дослідивши все від початку, по порядку описати тобі, високодостойний Феофиле,","щоб ти пізнав тверду основу того вчення, в якому був наставлений.","У дні Ірода, царя Юдейського, був священик на ім’я Захарія, з денної черги Авиєвої, і жінка його з дочок Ааронових, а ім’я її — Єлисавета.","Обоє вони були праведні перед Богом, виконуючи всі заповіді і настанови Господні бездоганно.","У них не було дітей, бо Єлисавета була неплідна, і обоє були вже похилого віку.","Одного разу, коли він за чином своєї черги служив перед Богом,","за звичаєм священства, йому випало покадити, ввійшовши до храму Господнього,","а вся безліч народу молилася зовні під час кадіння.","Тоді з’явився йому ангел Господній, стоячи праворуч жертовника кадильного.","Збентежився Захарія, побачивши його, і страх напав на нього.","Ангел же сказав йому: не бійся, Захаріє, бо почута молитва твоя, і жінка твоя Єлисавета народить тобі сина, і наречеш ім’я йому Іоан;","і буде тобі радість і втіха, і багато хто народженню його зрадіє,","бо він буде великий перед Господом; ні вина, ні хмільного напою не питиме, і Духа Святого сповниться ще від утроби матері своєї.","І багатьох з синів Ізраїлевих наверне до Господа Бога їхнього.","І йтиме перед Ним з духом і силою Іллі, щоб навернути серця батьків до дітей, і непокірних — до мудрості праведників, щоб приготувати Господеві народ звершений.","І сказав Захарія ангелові: з чого я пізнаю це? Бо я старий, і жінка моя постарілася у днях своїх.","Ангел сказав йому у відповідь: я Гавриїл, що стою перед Богом, і посланий говорити з тобою і благовістити тобі про це.","І ось ти будеш мовчати і не матимеш можливости говорити до того дня, коли збудеться це, за те, що ти не повірив словам моїм, котрі збудуться свого часу.","Люди чекали на Захарію і дивувалися, що він забарився в храмі.","Він же, вийшовши, не міг говорити до них; і вони зрозуміли, що він бачив видіння в храмі; і він говорив з ними знаками і залишався німим.","А коли закінчилися дні служіння його, повернувся до свого дому.","Після тих днів зачала Єлисавета, жінка його, і таїлася п’ять місяців, кажучи:","так сотворив мені Господь у ті дні, коли зглянувся на мене, щоб зняти з мене ганьбу перед людьми.","Шостого ж місяця був посланий від Бога ангел Гавриїл у галилейське місто, яке називається Назарет,","до Діви, зарученої з мужем на ім’я Йосиф, з дому Давидового; ім’я ж Діви — Марія.","Ангел, увійшовши до Неї, сказав: радуйся, Благодатна! Господь з Тобою, благословенна Ти в жонах.","Вона ж, побачивши його, стривожилася від слів його і міркувала, що б то значило це привітання.","І сказав Їй ангел: не бійся, Маріє! Бо Ти знайшла благодать у Бога.","І ось зачнеш в утробі і народиш Сина, і наречеш ім’я Йому Ісус.","Він буде Великий і Сином Всевишнього наречеться, і дасть Йому Господь Бог престіл Давида, отця Його.","І царюватиме у домі Якова повік, і царству Його не буде кінця.","Марія ж сказала ангелу: як же станеться це, коли Я мужа не знаю?","Ангел сказав Їй у відповідь: Дух Святий зійде на Тебе, і сила Всевишнього осінить Тебе. Тому і народжуване Святе наречеться Сином Божим.","Ось і Єлисавета, родичка Твоя, і вона зачала сина в старості своїй, і це вже шостий місяць їй, хоча називають її неплідною,","бо не буває безсилим у Бога ніяке слово.","Тоді Марія сказала: Я — раба Господня. Нехай буде Мені за словом твоїм. І відійшов від Неї ангел.","Уставши ж, Марія у дні ці поспіхом пішла у передгір’я, в місто Іудине,","і увійшла в дім Захарії, і привітала Єлисавету.","Коли ж почула Єлисавета привітання Маріїне, заграло дитя в утробі її, і сповнилася Духа Святого Єлисавета.","І вигукнула гучним голосом і сказала: благословенна Ти в жонах, і благословенний плід утроби Твоєї!","І звідки це мені, що Мати Господа мого прийшла до мене?","Бо, коли голос вітання Твого дійшов до вух моїх, заграло дитя радісно в утробі моїй.","Блаженна ж Та, Яка увірувала, бо збудеться сказане Їй від Господа.","І сказала Марія: величає душа Моя Господа,","і зрадів дух Мій у Бозі, Спасі Моїм,","бо зглянувся на смирення раби Своєї, ось-бо віднині ублажатимуть Мене всі роди.","Бо вчинив Мені велич Всемогутній, і святе ім’я Його.","І милість Його з роду в рід на тих, що бояться Його.","Явив могутність руки Своєї, розсіяв гордовитих у помислах сердець їхніх;","скинув сильних з престолів і підніс смиренних;","голодних сповнив благами, а тих, що багатіють, відпустив ні з чим.","Прийняв Ізраїля, отрока Свого, спом’янувши милість,","як говорив отцям нашим, Авраамові і нащадкам його до віку.","Пробула ж Марія з нею близько трьох місяців і повернулася в дім Свій.","Єлисаветі ж настав час родити, і вона народила сина.","І почули сусіди й родичі її, що звеличив її Господь милістю Своєю, і радувалися з нею.","І восьмого дня прийшли обрізати немовля, і хотіли назвати його ім’ям батька його — Захарією.","На це мати його сказала: ні, хай буде названий Іоаном.","І сказали їй: адже нікого нема в роді твоїм, хто звався б ім’ям тим.","І питали знаками в батька його, як би він хотів назвати його.","Попросивши дощечку, написав слова: Іоан буде ім’я йому. І дивувались усі.","І відразу відкрилися уста його і язик його, і він почав говорити, благословляючи Бога.","І був страх у всіх навколишніх жителів; і в усій країні Юдейській розповідалося про все це.","Усі, хто чув, поклали це в серці своїм і говорили: ким буде дитя це? І рука Господня була з ним.","І Захарія, батько його, сповнився Духа Святого і пророкував, кажучи:","благословен Господь Бог Ізраїлів, що відвідав народ Свій і створив визволення йому.","І підніс ріг спасіння нам у домі Давида, отрока Свого,","як провістив устами святих пророків Своїх, що були від віку,","що спасе нас від ворогів наших і від руки всіх, хто ненавидить нас;","сотворить милість батькам нашим і спом’яне святий завіт Свій —","дати нам клятву, якою клявся Він Авраамові, отцю нашому,","щоб ми, визволившись від рук ворогів наших,","безбоязно служили Йому в святості й праведності перед Ним всі дні життя нашого.","І ти, дитя, пророком Всевишнього наречешся, бо йтимеш перед лицем Господа, щоб приготувати путі Йому.","Дати зрозуміти спасіння людям Його у відпущенні гріхів їхніх,","з ласкавого милосердя Бога нашого, яким відвідав нас Схід* з неба,","просвітити тих, що у темряві й тіні смертній сидять, спрямувати ноги наші на шлях миру.","Дитя ж зростало і міцніло духом, і було у пустелях до дня явлення свого Ізраїлеві."],"x":{"2":"58.1.1|75.2.3","5":"12.24.10|17.12.17","9":"1.30.7|2.16.17|75.9.6","14":"52.1.58|53.5.35","17":"31.40.3|49.4.6|51.1.3|51.9.12|53.1.23","27":"50.1.18","31":"31.7.14|50.1.21","32":"9.7.12|25.131.11|31.9.7","33":"12.22.10|25.44.7|25.88.37|31.9.7|32.23.5|37.2.44|37.7.14|43.4.7","35":"37.9.24","46":"31.61.10|45.3.18","50":"25.102.17","51":"25.32.10|25.76.15|31.52.10","52":"24.5.11|31.66.2","53":"8.2.5|25.33.11|50.5.6","54":"25.97.3|31.41.8","55":"0.17.19|0.23.6|0.30.8-10","68":"50.1.21","69":"25.131.17|36.29.21","70":"25.71.4|32.23.6|32.30.8-10","72":"0.22.16|0.26.3|2.26.42|32.31.33","73":"75.6.13","74":"62.8.15|75.2.15","75":"56.1.15|66.4.24","76":"52.1.17","78":"32.23.5|48.3.8"},"n":{"2":["Ісуса Христа, Сина Божого."],"78":["Христос — Месія."]}},{"v":["У ті дні вийшов від кесаря Августа наказ зробити перепис по всій землі.","Цей перепис був перший за правління Квиринія Сирією.","І всі йшли записатися, кожен до свого міста.","Пішов також і Йосиф з Галилеї, з міста Назарета, до Юдеї, до міста Давидового, що зветься Вифлеєм, бо він був з дому і роду Давидового,","записатися з Марією, зарученою з ним жінкою, яка була вагітна.","Коли ж вони були там, надійшов час родити Їй;","І народила Сина Свого Первістка, і сповила Його, і поклала Його в ясла, бо не було їм місця в гостиниці.","У тій стороні були на полі пастухи, які стерегли нічної пори отару свою.","Аж ось ангел Господній став між них, і слава Господня осяяла їх; злякалися вони страхом великим.","І сказав їм ангел: не бійтеся; я благовіщу вам радість велику, яка буде всім людям.","Бо нині у місті Давидовому народився для вас Спаситель, Який є Христос Господь.","І ось вам знамення: ви знайдете сповите Немовля, Яке лежатиме в яслах.","І раптом з’явилося біля ангела численне воїнство небесне, яке славило Бога і викликувало:","слава у вишніх Богу і на землі мир, в людях благовоління!","І коли ангели відійшли від них на небо, пастухи сказали один одному: підемо до Вифлеєма і подивимось, що там сталося, про що сповістив нам Господь.","І, поспішивши, прийшли і знайшли Марію та Йосифа, і Немовля, Яке лежало в яслах.","Побачивши ж, розповіли про те, що було сповіщено їм про Немовля Це.","І всі, хто чув, дивувалися тому, що розповідали їм пастухи.","А Марія зберігала всі слова ці, складаючи в серці Своїм.","Пастухи ж повернулися, славлячи і хвалячи Бога за все те, що чули й бачили, як було сказано їм.","А як минуло вісім днів, коли належало обрізати Його, дали Йому ім’я Ісус, наречене ангелом ще перед тим, як зачався Він в утробі.","І коли настали дні очищення за законом Мойсеєвим, то принесли Його до Єрусалима, щоб поставити перед Господом,","як написано в законі Господньому, щоб усяка дитина чоловічої статі, яка розкриває утробу, була посвячена Господеві.","І щоб принести в жертву, як сказано в законі Господньому, дві горлиці або двоє голуб’ят.","Був тоді в Єрусалимі чоловік на ім’я Симеон. Він був муж праведний та благочестивий, що чекав утіхи Ізраїлевої, і Дух Святий був на ньому.","Йому було провіщено Духом Святим, що він не побачить смерти, доки не побачить Христа Господнього.","І був він приведений Духом у храм. І коли батьки принесли Немовля Ісуса, щоб зробити з Ним за законним звичаєм,","він взяв Його на руки, благословив Бога і сказав:","нині відпускаєш раба Твого, Владико, за словом Твоїм, з миром,","бо бачили очі мої спасіння Твоє,","яке Ти приготував перед лицем усіх народів,","світло на просвітлення язичників і славу народу Твого Ізраїля.","Йосиф же і Мати Його дивувалися сказаному про Нього.","І благословив їх Симеон і сказав Марії, Матері Його: ось лежить Цей на падіння і на піднесення багатьох в Ізраїлі і на знак сперечання, —","і Тобі Самій душу пройме меч, — щоб відкрилися помисли багатьох сердець.","Тут була й Анна-пророчиця, дочка Фануїлова, з коліна Асирова, яка досягла глибокої старости, проживши з чоловіком сім років від дівоцтва свого;","вдова вісімдесяти чотирьох років, яка не відходила від храму, постом і молитвою служачи день і ніч.","Прийшовши тієї години, вона славила Господа і говорила про Нього всім, хто чекав спасіння в Єрусалимі.","І коли виконали все за законом Господнім, повернулися до Галилеї, до міста свого Назарета.","Дитя зростало і міцніло духом, сповнюючись премудрости, і благодать Божа була на Ньому.","Щороку батьки Його ходили до Єрусалима на свято Пасхи.","І коли було Йому дванадцять років, прийшли вони також за звичаєм до Єрусалима на свято.","Як скінчилися дні свята, вони повертались, а Отрок Ісус залишився в Єрусалимі; і не помітили того Йосиф і Мати Його.","Думали, що Він іде з іншими; пройшовши ж день дороги, почали шукати Його серед родичів та знайомих.","І, не знайшовши Його, повернулись до Єрусалима, шукаючи Його.","Через три дні знайшли Його в храмі, де Він сидів серед учителів, слухав їх і розпитував;","усі, хто слухав Його, дивувалися розуму і відповідям Його.","І, побачивши Його, здивувалися; і Мати Його сказала Йому: Чадо! Що Ти зробив з нами? Ось батько Твій і Я, вболіваючи, шукали Тебе.","Він сказав їм: навіщо вам було шукати Мене? Хіба ви не знали, що Я маю бути в тому, що належить Отцю Моєму?","Але вони не зрозуміли сказаних Ним слів.","І Він пішов з ними, і прийшов у Назарет, і корився їм. І Мати Його зберігала всі слова ці в серці Своєму.","Ісус же зростав у премудрості і віком, в любові у Бога і людей."],"x":{"4":"8.16.1:4|53.7.42","7":"50.2.1","14":"31.2.4|31.44.23|31.49.13|31.57.19|43.4.3|52.19.38|62.5.1","21":"0.17.12|2.12.3|50.1.21","23":"1.13.2:12|1.22.29|1.34.19|3.8.16","24":"2.12.6:8","25":"52.24.21","30":"0.49.18|8.2.1|25.97.3|31.52.10","32":"31.9.2|31.42.6|31.60.3|54.13.47","34":"31.8.14|50.21.44|56.2.7|62.9.32","35":"53.19.25","37":"71.5.5","40":"52.2.52","41":"1.23.17|1.34.23","47":"50.7.28|51.1.22|52.4.32|53.7.15"}},{"v":["У п’ятнадцятий же рік правління Тиверія-кесаря, коли Понтійський Пилат правив Юдеєю, Ірод був четвертовладником у Галилеї, Филип, брат його, був четвертовладником в Ітуреї і Трахонітському краї, а Лисаній був четвертовладником в Авилинеї,","за первосвящеників Анни і Каяфи, було слово Боже до Іоана, сина Захарії, в пустелі.","І він проходив по всій околиці Йорданській, проповідуючи хрещення покаяння для прощення гріхів,","як написано в книзі слів Ісаї-пророка, який говорить: глас вопіющого в пустелі: приготуйте путь Господній, прямими зробіть стезі Йому.","Кожна долина нехай наповниться, і всяка гора і пагорб зрівняються, і хай стане криве прямим, і вибоїсті дороги — рівними.","І побачить всяка плоть спасіння Боже.","Іоан говорив народові, що приходив хреститися від нього: поріддя єхиднове! Хто навчив вас тікати від грядущого гніву?","Створіть же плоди, достойні покаяння, і не думайте говорити в собі: отця маємо Авраама. Кажу бо вам, що Бог з каміння цього може створити дітей Авраамові.","Вже й сокира при корені дерева лежить: всяке дерево, що не приносить доброго плоду, зрубується і вкидається у вогонь.","І запитували його люди, кажучи: що ж нам робити?","Відповідаючи, він сказав їм: хто має дві одежини, хай дасть тому, хто не має, і хто має їжу, хай зробить так само.","Прийшли і митарі хреститися від нього і сказали йому: учителю, що нам робити?","Він відповів їм: нічого не вимагайте більше того, що призначено вам.","Питали його також і воїни: а що нам робити? І сказав їм: нікого не кривдіть, не обмовляйте і задовольняйтеся платнею вашою.","Коли ж народ чекав і всі роздумували в серцях своїх про Іоана, чи не Христос він, —","Іоан усім відповідав: я хрещу вас водою: але гряде Сильніший за мене, Якому я недостойний розв’язати ремінь взуття Його; Він хреститиме вас Духом Святим і вогнем.","Лопата в руці Його, і Він очистить тік Свій і збере пшеницю в житницю Свою, а полову спалить вогнем невгасимим.","І багато іншого, втішаючи, благовістив Він людям.","Ірод же, четвертовладник, якому Іоан докоряв за Іродіаду, жінку брата його, і за все, що зробив Ірод лихого,","додав до всього іншого і те, що замкнув Іоана у в’язниці.","І сталося, коли хрестився весь народ, і Ісус, охрестившись, молився, розкрилося небо,","і Дух Святий зійшов на Нього в тілесному вигляді, як голуб; і був Голос з небес, Який говорив: Ти є Син Мій Улюблений, у Тобі Моє благовоління!","Ісус, починаючи Своє служіння, був років тридцяти, і був, як думали, син Йосифів, Іліїв,","Матфатів, Левіїв, Мелхіїв, Іаннаїв, Йосифів,","Маттафіїв, Амосів, Наумів, Еслимів, Наггеїв,","Маафів, Маттафіїв, Семеіїв, Йосифів, Іудин,","Іоананів, Рисаїв, Зоровавелів, Салафіїлів, Ниріїв,","Мелхіїв, Аддіїв, Косамів, Елмодамів, Ірів,","Іосіїв, Єлиєзерів, Іоримів, Матфатів, Левіїв,","Симеонів, Іудин, Йосифів, Іонанів, Єлиакимів,","Мелеаїв, Маїнанів, Маттафаїв, Нафанів, Давидів,","Єссеїв, Овидів, Воозів, Салмонів, Наасонів,","Аминадавів, Арамів, Єсромів, Фаресів, Іудин,","Яковів, Ісааків, Авраамів, Фаррин, Нахорів,","Серухів, Рагавів, Фалеків, Єверів, Салинів,","Каїнанів, Арфаксадів, Симів, Ноїв, Ламехів,","Мафусалів, Єнохів, Іаредів, Малелеїлів, Каїнанів,","Єносів, Сифів, Адамів, Божий."],"x":{"3":"50.3.1|51.1.4","4":"50.3.3|51.1.3|53.1.23","6":"31.40.3-5","7":"50.3.7","8":"50.3.9|50.8.11|53.8.39","9":"50.3.10|50.7.19|53.15.6","11":"55.2.15|58.3.17|64.8.14","12":"50.21.32","16":"50.3.11|51.1.7|53.1.15|54.1.5","17":"50.3.12","19":"50.14.3|51.6.17","21":"50.3.16|51.1.10|53.1.32","23":"50.13.55|51.6.3|52.4.22|53.6.42","34":"0.11.24-26","35":"0.11.20-22","36":"0.5.28-29|0.6.10|0.11.10","37":"0.5.12","38":"0.5.3"}},{"v":["Ісус же, сповнений Духа Святого, повернувся від Йордану і поведений був Духом у пустелю.","Там сорок днів він був спокушуваний дияволом і нічого не їв у ті дні, і по їх закінченні наостанку зголоднів.","І сказав Йому диявол: якщо Ти Син Божий, то звели каменю цьому, щоб став хлібом.","Ісус відповів йому: написано, що не хлібом єдиним житиме людина, але всяким словом Божим.","І, вивівши Його на високу гору, диявол показав Йому всі царства світу в одну мить.","І сказав Йому диявол: Тобі дам усю оцю владу над усіми цими царствами і славу їх, бо вона мені передана, і я кому схочу, даю її.","Отже, якщо Ти поклонишся мені, то все буде Твоє.","Ісус сказав йому у відповідь: відійди від Мене, сатано; написано: Господу Богу твоєму поклоняйся і Йому Єдиному служи.","І повів Його до Єрусалима, і поставив Його на крилі храму, і сказав Йому: якщо Ти Син Божий, кинься звідси вниз.","Бо написано: ангелам Своїм заповість про Тебе зберегти Тебе;","і на руках понесуть Тебе, щоб не спіткнувся об камінь ногою Твоєю.","Ісус відповів йому: сказано: не спокушай Господа Бога твого.","І, закінчивши всі спокушання, диявол відійшов від Нього до часу.","І повернувся Ісус в силі духу до Галилеї; і рознеслася чутка про Нього по всьому краю.","Він навчав у синагогах їхніх, і всі Його славили.","І прийшов у Назарет, де був вихований, і увійшов, за звичаєм Своїм, в день суботній у синагогу і став, щоб читати.","Йому подали книгу пророка Ісаї; і Він, розгорнувши книгу, знайшов місце, де було написано:","Дух Господній на Мені; бо Він помазав Мене благовістити убогим, і послав Мене зціляти розбитих серцем, проповідувати полоненим визволення, сліпим прозріння, відпустити замучених на волю,","проповідувати літо Господнє сприятливе.","І, згорнувши книгу і віддавши служителю, сів, і очі всіх у синагозі були звернені до Нього.","І Він почав говорити їм: нині справдилося писання, яке ви почули.","І всі свідчили Йому. І дивувалися словам благодаті, що виходили з уст Його, і говорили: чи ж не Йосифів це син?","Він сказав їм: напевно, ви скажете Мені приказку: лікарю, зцілися Сам, зроби і тут, на Твоїй батьківщині, те, що, ми чули, було в Капернаумі.","І сказав: істинно кажу вам: ніякого пророка не приймають на батьківщині своїй.","По правді ж кажу вам, багато вдів було в Ізраїлі у дні Іллі, коли небо замкнулося на три роки і шість місяців, так що настав великий голод по всій землі,","і до жодної з них не був посланий Ілля, а тільки в Сарепту сидонську, до жінки-вдови.","І багато також було прокажених в Ізраїлі за пророка Єлисея, і жоден з них не очистився, тільки Неєман-сирієць.","І сповнились усі гнівом у синагозі, почувши це.","І, вставши, вигнали Його геть з міста і повели на вершину гори, на якій було збудоване їхнє місто, щоб скинути Його.","Він же, пройшовши серед них, відійшов.","І прийшов у Капернаум, місто галилейське, і навчав їх по суботах.","І дивувалися вченню Його, бо слово Його мало владу.","Був у синагозі чоловік, що мав духа нечистого, і він закричав гучним голосом:","облиш, що Тобі до нас, Ісусе Назарянине? Ти прийшов погубити нас; знаю Тебе, хто Ти, Святий Божий.","Ісус заборонив йому, сказавши: замовкни і вийди з нього. І біс, кинувши його посередині синагоги, вийшов з нього, нітрохи не зашкодивши йому.","І усіх охопив жах, і питали один одного, кажучи: що це за слово, що з владою і силою наказує нечистим духам, і вони виходять?","І розійшлася чутка про Нього по всіх місцях того краю.","Вийшовши з синагоги, Він увійшов у дім Симонів; теща ж Симонова була в сильній гарячці; і благали Його за неї.","Підійшовши до неї, Він заборонив гарячці; і покинула її. Вона відразу ж встала і слугувала їм.","Коли ж заходило сонце, всі, хто тільки мав хворих на різні недуги, приводили їх до Нього, і Він, покладаючи на кожного з них руки, зціляв їх.","Виходили також і біси з багатьох, викрикуючи і кажучи: Ти Христос, Син Божий. А Він забороняв їм казати, що вони знають, що Він Христос.","А як настав день, Він, вийшовши з дому, пішов у безлюдне місце, а люди шукали Його і, прийшовши до Нього, затримували Його, щоб не йшов від них.","Він же сказав їм: і іншим містам Мені належить благовістити Царство Боже, бо на те Я посланий.","І проповідував у синагогах галилейських."],"x":{"1":"50.4.1|51.1.12","4":"4.8.3|50.4.4","8":"4.10.20|50.4.10","10":"50.4.6","11":"25.90.11-12","12":"4.6.16|50.4.7","14":"50.4.12|51.1.14|53.4.43","16":"50.13.54|51.6.1","19":"31.61.1-2","24":"50.13.57|51.6.4|53.4.44","25":"10.17.10|55.5.17","27":"11.5.14","31":"50.4.13|51.1.21","32":"50.7.28|51.1.22|52.2.47","33":"51.1.23","38":"50.8.14|51.1.29","40":"50.8.16|51.1.32","41":"51.1.34|51.3.12","43":"51.1.38"}},{"v":["Одного разу, коли народ тиснувся до Нього, щоб слухати Слово Боже, а Він стояв біля озера Генісаретського,","і побачив Він два човни, що стояли при озері; а рибалки, вийшовши з них, полоскали сіті.","Увійшовши в один з човнів, який належав Симонові, Він просив його відплисти трохи від берега і, сівши, навчав людей з човна.","Коли ж перестав навчати, сказав Симонові: відпливи на глибину і закиньте сіті свої для лову.","Симон сказав Йому у відповідь: Наставнику, ми трудилися всю ніч і нічого не впіймали, але за словом Твоїм закину сіть.","Зробивши це, вони наловили дуже багато риби, аж проривалася сіть у них.","І дали знак друзям з другого човна, щоб прийшли допомогти їм; і прийшли, і наповнили обидва човни так, що вони почали тонути.","Побачивши це, Симон-Петро припав до колін Ісусових і сказав: Господи, відійди від мене, бо я чоловік грішний!","Бо жах охопив його і всіх, що були з ним, від того улову риби, яку зловили;","також і Якова та Іоана, синів Зеведеєвих, які були спільниками Симона. І сказав Ісус Симонові: не бійся, віднині будеш ловцем людей.","І, витягнувши обидва човни на берег, залишили все і пішли за Ним.","Коли Ісус був в одному місті, прийшов чоловік, увесь в проказі, і, побачивши Ісуса, упав ниць і благав Його: Господи, якщо Ти хочеш, можеш мене очистити.","Він простяг руку, доторкнувся до нього і сказав: хочу, очисться. І відразу проказа зійшла з нього.","І Він звелів йому нікому не говорити, а піти показатися священикові і принести жертву за очищення своє, як повелів Мойсей, на свідчення їм.","Розійшлася ще більше чутка про Нього, і сходилося до Нього безліч народу послухати і зцілитися від Нього від недуг своїх.","Він же відходив у безлюдні місця і молився.","Одного дня, коли Він навчав, і сиділи тут фарисеї і законовчителі, що поприходили з усяких місць Галилеї та Юдеї і з Єрусалима, і сила Господня являлася у зціленні хворих, —","і ось люди принесли на постелі чоловіка, який був розслаблений, і намагалися внести його в дім і покласти перед Ним;","і, не знайшовши, як пронести його через натовп, вилізли на дім і через покрівлю спустили його з постіллю на середину, перед Ісусом.","І Він, побачивши віру їхню, сказав йому: чоловіче, відпускаються тобі гріхи твої.","Книжники і фарисеї почали розмірковувати, кажучи: хто ж є Цей, що богохульствує? Хто може відпускати гріхи, крім одного Бога?","Ісус, зрозумівши міркування їхні, сказав їм у відповідь: що помишляєте в серцях ваших?","Що легше — сказати: відпускаються тобі гріхи твої, чи сказати: встань і ходи?","Але щоб ви знали, що Син Людський має владу на землі відпускати гріхи, — сказав Він розслабленому: тобі кажу, встань, візьми постіль твою та йди в дім твій.","І він відразу встав перед ними, взяв те, на чому лежав, та й пішов до дому свого, славлячи Бога.","І жах охопив усіх, і славили Бога і, сповнені страхом, говорили: преславне бачили ми нині.","І після цього вийшов Ісус і побачив митаря на ім’я Левій, що сидів на митниці, і сказав йому: йди за Мною.","І той, покинувши все, встав і пішов услід за Ним.","І влаштував Йому Левій у домі своїм велику гостину; і там було багато митарів та інших, які возлежали з ними.","Книжники ж і фарисеї нарікали на Нього і говорили ученикам Його: чому ви їсте і п’єте з митарями та грішниками?","Ісус же сказав їм у відповідь: не здорові потребують лікаря, а недужі.","Я прийшов покликати не праведників до покаяння, але грішників.","Вони ж сказали Йому: чому учні Іоанові часто постять і моляться, також і фарисейські, а Твої їдять і п’ють?","Він же сказав їм: чи можете примусити гостей весільних постити, доки з ними жених?","Але прийдуть дні, коли забраний буде від них жених, і тоді поститимуть у ті дні.","Сказав же і притчу їм: ніхто не накладає латки до старої одежі, відірвавши від нової одежі; а інакше і нове розірветься, і до старого не підійде те, що з нового.","І ніхто не вливає молодого вина в старі міхи, і саме виллється, і міхи пропадуть.","А молоде вино в нові міхи треба вливати; тоді збережеться і те, і друге.","І ніхто, пивши старе вино, не захоче зараз же молодого, бо скаже: старе краще."],"x":{"12":"50.8.2|51.1.40","14":"2.14.3-4|50.8.4|51.1.44","18":"50.9.2|51.2.3","27":"50.9.9|51.2.14","32":"50.9.13|51.2.17","36":"50.9.16|51.2.21"}},{"v":["Сталося, що у суботу, першу після другого дня Пасхи, довелося Йому йти через посіви, і ученики Його зривали колоски і їли, розтираючи руками.","Деякі ж з фарисеїв сказали їм: навіщо ви робите те, чого не годиться робити в суботу?","Ісус сказав їм у відповідь: хіба ви не читали, що вчинив Давид, коли зголоднів сам і ті, що були з ним?","Як він увійшов у дім Божий, і взяв хліби принесення*, і їв, і дав тим, що були з ним, хоча їх не можна було їсти нікому, тільки одним священикам.","І сказав їм: бо Син Людський є господарем і суботи.","Довелося ж і в іншу суботу увійти Йому в синагогу і навчати. Там був чоловік, у якого права рука була суха.","Книжники ж і фарисеї стежили за Ним, чи не зцілить Він у суботу, щоб знайти звинувачення проти Нього.","Він же, знаючи помисли їхні, сказав чоловікові, що мав суху руку: встань і вийди на середину. І він встав і вийшов.","Тоді сказав їм Ісус: запитаю вас, що годиться робити в суботу — добро чи зло? Спасти душу чи згубити? Вони мовчали.","І, поглянувши на всіх них, сказав тому чоловікові: простягни руку твою. Він так і зробив; і стала рука його здорова, як і друга.","Вони ж розлютилися і говорили між собою, що б їм вчинити з Ісусом.","У ті дні Ісус зійшов на гору помолитися і пробув усю ніч у молитві до Бога.","Коли ж настав день, покликав учеників Своїх і обрав з них дванадцятьох, яких назвав апостолами:","Симона, якого назвав Петром, і Андрія, брата його, Якова та Іоана, Филипа та Варфоломія,","Матфея та Фому, Якова Алфеєвого та Симона, званого Зилотом, Іуду Якового та","Іуду Іскаріотського, який потім став зрадником.","І зійшовши з ними, Він став на рівному місці; також багато учеників Його і безліч народу з усієї Юдеї та Єрусалима, з приморських місць Тирських і Сидонських,","що прийшли послухати Його і зцілитися від недуг своїх, також і ті, що страждали від нечистих духів, — і зцілялися.","І весь народ намагався доторкнутися до Нього, бо від Нього виходила сила і зціляла всіх.","І Він, звівши очі Свої на учеників Своїх, говорив: Блаженні убогі духом, бо ваше є Царство Боже.","Блаженні ті, що жадають тепер, бо насититеся. Блаженні ті, що плачуть тепер, бо втішитеся.","Блаженні будете, коли зненавидять вас люди і коли розлучать вас і ганьбитимуть, і знеславлять ім’я ваше заради Сина Людського.","Радійте того дня і веселіться, бо велика вам нагорода на небесах. Так робили пророкам батьки їхні.","Але горе вам, багаті, бо ви вже одержали свою втіху.","Горе вам, ситі нині, бо будете голодувати. Горе вам, що смієтесь тепер, бо будете плакати і ридати!","Горе вам, коли всі люди говоритимуть про вас добре, бо так робили лжепророкам батьки їхні.","Але вам, хто слухає, кажу: любіть ворогів ваших, добро творіть тим, хто ненавидить вас;","благословляйте тих, хто проклинає вас, і моліться за тих, хто кривдить вас.","Хто вдарить тебе по щоці, підстав і другу, і хто забирає в тебе верхній одяг, не борони взяти і сорочку.","Кожному, хто просить у тебе, дай, а від того, хто забирає твоє, не вимагай.","І як хочете, щоб робили вам люди, так і ви робіть їм.","І коли ви любите тих, хто вас любить, яка вам за те дяка? Бо і грішники люблять тих, хто їх любить.","І якщо ви робите добро тим, хто вам робить добро, яка вам за те дяка? Бо і грішники те саме роблять.","І коли позичаєте тим, від кого сподіваєтесь одержати, яка за те вам дяка? Бо і грішники позичають грішникам, щоб стільки ж одержати.","Але ви любіть ворогів ваших, добро творіть і позичайте, нічого не сподіваючись; і буде вам нагорода велика, і будете синами Всевишнього; бо Він добрий і до невдячних, і злих.","Отже, будьте милосердні, як і Отець ваш милосердний.","Не судіть, то і вас не судитимуть; не осуджуйте, то й вас не осудять; прощайте, то й вас прощатимуть;","давайте, і дасться вам: мірою доброю, натоптаною, утрушеною, переповненою віддадуть вам, бо якою мірою міряєте, такою ж відміряється і вам.","Сказав же їм притчу: чи може сліпий сліпого водити? Чи не впадуть обидва в яму?","Учень не буває вищим від свого учителя; але, удосконалившись, кожен буде, як і вчитель його.","Що ж ти бачиш скалку в оці брата твого, а колоди, що є в оці твоєму, не відчуваєш?","Або, як можеш сказати братові твоєму: брате, дай я вийму скалку з ока твого, коли сам не бачиш колоди у своєму оці? Лицеміре! Вийми перше колоду з ока свого, і тоді побачиш, як вийняти скалку з ока брата твого.","Нема доброго дерева, яке родило б поганий плід, і немає поганого дерева, яке родило б плід добрий.","Бо всяке дерево пізнається за плодом своїм: не збирають смокви з терня і не знімають винограду з чагарника.","Добра людина з доброго скарбу серця свого виносить добре, а зла людина з лихого скарбу серця свого виносить зле: бо з повноти серця промовляють уста її.","Чому ж ви Мене кличете: Господи! Господи! — а не робите того, що Я кажу?","Всякий, хто приходить до Мене та слухає слова Мої і виконує їх, — скажу вам, до кого подібний.","Він подібний до людини, яка, будуючи дім, вкопала, заглибила і поклала основу на камені; коли ж сталася повінь і вода підступила до того дому, то не могла його зрушити, бо він був збудований на камені.","А хто слухає і не виконує, той подібний до людини, яка збудувала дім на землі без основи, то як тільки ринула на нього вода, він зараз же розвалився; і руйнування дому того було велике."],"x":{"1":"4.23.25|50.12.1|51.2.23","3":"8.21.6|50.12.4|51.2.26","4":"1.29.32|2.8.31|2.24.9|50.12.4|51.2.26","6":"50.12.9|51.3.1","13":"50.10.1|51.3.13","17":"50.4.25","19":"51.5.30","20":"50.5.3","21":"31.55.1|31.61.2|31.66.13","22":"50.5.11","23":"13.36.16|17.9.26|31.35.10","25":"26.14.13|31.65.13","26":"31.30.10|53.7.7","27":"1.23.4|26.25.21|50.5.44","29":"50.5.39|62.12.17|63.6.7","31":"18.4.15|50.7.12","35":"4.15.8|50.5.45","36":"50.5.48","37":"50.7.2|62.2.1|63.4.5","38":"26.19.17|50.7.2|51.4.24","39":"31.42.19|50.15.14","40":"50.10.24|53.13.16|53.15.20","41":"50.7.3","42":"26.18.18","43":"50.7.18|50.12.33","44":"50.7.16","45":"50.12.34-35","46":"49.1.6|50.7.21|55.1.22|62.2.13","48":"50.7.24"},"n":{"4":["Священні хліби, що виставлялися в храмі."]}},{"v":["Коли ж Він скінчив усі слова Свої до людей, що слухали Його, то увійшов до Капернаума.","У одного сотника був хворий при смерті слуга, яким той дорожив.","Почувши про Ісуса, він послав до Нього старійшин юдейських просити Його, щоб прийшов зцілити слугу його.","І вони, прийшовши до Ісуса, щиро благали Його, кажучи: він достойний, щоб Ти зробив для нього це,","бо любить народ наш і збудував нам синагогу.","Ісус пішов з ними. І коли Він був уже недалеко від дому, сотник послав до Нього друзів сказати Йому: Господи, не трудися, бо я недостойний, щоб Ти під дах мій увійшов.","Тому і самого себе не вважаю я достойним прийти до Тебе; але скажи тільки слово, і одужає слуга мій.","Бо і я, людина підвладна, маючи під собою воїнів, кажу одному: йди, і він іде; і другому: прийди, і приходить; і слузі моєму: роби те, і робить.","Почувши це, Ісус здивувався йому і, повернувшись, сказав до народу, що йшов за Ним: кажу вам, що навіть в Ізраїлі Я не знайшов такої віри.","Посланці, повернувшись у дім, знайшли хворого слугу здоровим.","Після цього Ісус пішов до міста, що зветься Наїн; і з Ним ішло багато учеників Його і безліч народу.","Коли ж Він підійшов до воріт міста, саме виносили померлого, єдиного сина у матері, а вона була вдова; і чимало народу йшло з нею з міста.","Побачивши її, Господь змилосердився над нею і сказав їй: не плач.","І, підійшовши, доторкнувся до мар; ті, що несли, зупинилися, і Він сказав: юначе, тобі кажу, встань!","І мертвий сів і почав говорити; і віддав його Ісус матері його.","І всіх охопив страх, і славили Бога, кажучи: великий пророк постав між нами, і Бог відвідав народ Свій.","Така чутка про Нього розійшлася по всій Юдеї і по всьому тому краю.","І сповістили про все те Іоана учні його.","Іоан, прикликавши двох з учнів своїх, послав до Ісуса спитати: чи Ти Той, Хто має прийти, чи іншого нам чекати?","Вони, прийшовши до Ісуса, сказали: Іоан Хреститель послав нас до Тебе спитати — чи Ти Той, Хто має прийти, чи іншого нам чекати?","А в той час Він зцілив багатьох від недуг і ран, і від злих духів, і багатьом сліпим дарував прозріння.","І сказав їм Ісус у відповідь: підіть, розкажіть Іоанові, що ви бачили і чули: сліпі прозрівають, криві ходять, прокажені очищаються, глухі чують, мертві воскресають, убогі благовістять.","І блаженний той, хто не спокуситься через Мене!","А як одійшли учні Іоана, Він почав говорити народові про Іоана: на що ходили ви дивитися в пустелю? Чи на тростину, що вітер колише?","На кого ходили дивитися? Чи на людину, одягнену в м’який одяг? Але ті, що одягаються пишно та живуть у розкошах, знаходяться в царських палатах.","На що ж ви ходили дивитися? На пророка? Так, кажу вам, і більше, ніж на пророка.","Це той, про кого написано: ось Я посилаю ангела Мого перед лицем Твоїм, який приготує путь Твою перед Тобою.","Бо кажу вам: з народжених жінками немає жодного пророка, більшого за Іоана Хрестителя, але найменший у Царстві Божому більший за нього.","І всі люди, що слухали Його, навіть і митарі, визнавши славу Бога, хрестилися хрещенням Іоановим.","Фарисеї ж і законники відкинули волю Божу про себе і не хрестилися від нього.","Тоді Господь сказав: кому уподібню людей роду цього і до кого вони подібні?","Вони подібні до дітей, що сидять на торжищах і кличуть одне одного й кажуть: ми грали вам на сопілці, а ви не танцювали; ми співали вам жалібних пісень, а ви не плакали.","Бо прийшов Іоан Хреститель, який ні хліба не їсть, ні вина не п’є, і говорите: він біса має.","Прийшов Син Людський, Який їсть і п’є, і говорите: ось чоловік, Який любить їсти, пити вино, друг митарям і грішникам.","І виправдалася премудрість всіма дітьми своїми*.","Один з фарисеїв просив Його, щоб спожив з ним їжі, і Він, прийшовши в дім фарисея, возліг.","І ось жінка з того міста, яка була грішницею, довідавшись, що Він перебуває в домі фарисея, принесла алавастрову посудину з миром","і, припавши до ніг Його ззаду, плачучи, почала обмивати ноги Його слізьми і обтирати волоссям голови своєї, цілувала ноги Його і мастила миром.","Фарисей же, що запросив Його, побачивши це, сказав сам собі: якби Він був пророком, то знав би, хто і яка жінка доторкається до Нього, бо вона грішниця.","Звернувшись до нього, Ісус сказав: Симоне, я маю тобі дещо сказати. Він же говорить: кажи, Вчителю.","Ісус сказав: у одного лихваря було два боржники, один винен був п’ятсот динаріїв, а другий п’ятдесят.","Коли ж вони не мали чим віддати, він простив обом. Скажи ж, котрий з них більше полюбить його?","У відповідь Симон сказав: думаю, що той, якому більше простив. Він сказав: правильно ти розсудив.","І, обернувшись до жінки, сказав Симонові: чи бачиш цю жінку? Я прийшов у дім твій, і ти не дав Мені води на ноги, вона ж слізьми обливала ноги Мої і волоссям голови своєї обтерла.","Ти цілування не дав Мені, а вона, відколи Я прийшов, не перестає цілувати ноги Мої.","Ти оливою не помастив голови Моєї, вона ж миром намастила ноги Мої.","Через те кажу тобі: прощаються гріхи її численні за те, що вона полюбила багато, а кому мало прощається, той мало любить.","Їй же сказав: прощаються тобі гріхи.","Ті, що були з Ним, почали говорити про себе: хто Він, що й гріхи прощає?","Він же сказав жінці: віра твоя спасла тебе; йди з миром."],"x":{"1":"50.8.5","16":"52.1.68|53.6.14","18":"50.11.2","19":"0.49.10|31.35.4|37.9.24|53.6.14","22":"25.145.8|31.29.18|31.35.5|31.42.7|31.61.1|50.11.5|52.4.18","23":"31.8.14|50.11.6|56.2.8","27":"49.3.1|50.11.10|51.1.2","28":"50.11.11","29":"50.21.31","30":"54.20.27","31":"50.11.16","37":"50.26.7|51.14.3|53.11.2|53.12.3","39":"52.15.2"},"n":{"35":["У грецькому тексті: ділами своїми."]}},{"v":["Після цього проходив Він по містах і селах, проповідуючи і благовістячи Царство Боже, і з Ним дванадцять.","І деякі жінки, яких Він зцілив від злих духів і недуг: Марія, звана Магдалиною, з якої вийшло сім бісів,","та Іоанна, жінка Хузи, домоправителя Іродового, і Сусанна, і багато інших, які служили Йому з майна свого.","Коли ж зібралося багато народу, і з усіх міст жителі сходилися до Нього, Він почав говорити притчу:","вийшов сівач сіяти зерно своє і, коли сіяв, одне впало при дорозі, і було потоптане, і птахи небесні подзьобали його.","А інше впало на каміння і, зійшовши, всохло, бо не мало вологи.","А ще інше впало поміж терня, і виросло терня і заглушило його.","Інше ж упало в добру землю і, коли зійшло, дало плід у стократ. Сказавши це, виголосив: хто має вуха слухати, нехай слухає!","Ученики ж Його запитали в Нього: що означає притча ця?","Він сказав: вам дано розуміти таємниці Царства Божого, а іншим — у притчах, щоб вони, дивлячись, не бачили і, слухаючи, не розуміли.","Ось що означає притча ця. Зерно — це слово Боже.","А те, що впало при дорозі, це ті, що слухають, але потім приходить диявол і забирає слово із серця їхнього, щоб вони не увірували і не спаслись.","А те, що на камінні, це ті, що, як тільки почують слово, з радістю приймають, але не мають кореня, дочасно вірують, а під час спокуси відпадають.","А те, що впало поміж терня, це ті, що слухають слово, але відходять і, заглушені турботами, багатством та життєвими насолодами, не дають плоду.","А те, що впало в добру землю, це ті, які добрим і щирим серцем почуте слово бережуть і приносять плід у терпінні. Сказавши це, Він виголосив: хто має вуха слухати, нехай слухає.","Ніхто, засвітивши світильник, не покриває його посудиною або не ставить під ліжко, а ставить на свічник, щоб ті, що входять, бачили світло.","Бо немає нічого таємного, що не стало б явним, ні прихованого, що не стало б відомим і не відкрилося б.","Отже, пильнуйте, як слухаєте: бо хто має, тому дасться, а хто не має, у того відбереться і те, що він думає мати.","Прийшли до Нього Мати і брати Його, і не могли доступитися до Нього через народ.","І сповістили Його, кажучи: Мати Твоя і брати Твої стоять зовні, бажаючи бачити Тебе.","Він же сказав їм у відповідь: мати Моя і брати Мої — це ті, що слухають слово Боже і виконують його.","Одного дня увійшов Він у човен з учениками Своїми і сказав їм: переправимось на той бік озера. І вирушили.","Коли пливли вони, Він заснув. Знялася буря велика на озері, і заливало їх хвилями, і вони були в небезпеці.","І, приступивши, вони розбудили Його, кажучи: Наставнику! Наставнику, гинемо! Він же, вставши, заборонив вітрові і хвилям; і вони уляглись, і настала тиша.","Тоді Він сказав їм: де віра ваша? Вони ж у страху і здивуванні говорили один одному: Хто ж Цей, що й вітрам і воді наказує, і слухаються Його?","І припливли в землю Гадаринську, що навпроти Галилеї.","Коли ж Він зійшов на берег, зустрів Його один чоловік з міста, що упродовж багатьох років мав бісів, і не вдягався в одяг, і жив не в домі, а в гробах.","Побачивши ж Ісуса, він закричав, припав до Нього і гучним голосом сказав: що Тобі до мене, Ісусе, Сину Бога Вишнього? Благаю Тебе, не муч мене!","Бо Ісус повелів нечистому духові вийти з цього чоловіка, тому що він багато років мучив його; і в’язали його ланцюгами залізними і путами, і стерегли його, але він розривав ланцюги, і гнав його біс у пустелю.","Ісус запитав його: як твоє ім’я? Він же сказав: легіон, — бо багато бісів увійшло в нього.","І вони благали Ісуса, щоб не повелів їм іти в безодню.","Тут же на горі паслося велике стадо свиней. І біси благали Його, щоб дозволив їм увійти в них, і повелів їм.","Біси, вийшовши з чоловіка, увійшли в свиней, і кинулося стадо з кручі в озеро, і потонуло.","Пастухи, побачивши, що сталося, побігли і розповіли в місті і по селах.","І вийшли побачити, що сталось; і, прийшовши до Ісуса, знайшли чоловіка, з якого вийшли біси, одягненого і при своєму розумі, котрий сидів біля ніг Ісусових, і вжахнулися.","А ті, що бачили, розповіли їм, як зцілився біснуватий.","І весь народ краю Гадаринського просив Його відійти від них, бо їх охопив великий страх. Він увійшов у човен і повернувся.","Чоловік же, з якого вийшли біси, благав Його, щоб бути з Ним. Але Ісус відпустив його, сказавши:","повернись у дім твій і розкажи, що сотворив тобі Бог. Він пішов і проповідував по всьому місту, що сотворив йому Ісус.","Коли ж Ісус повернувся, народ прийняв Його, бо всі чекали на Нього.","І ось прийшов чоловік на ім’я Іаїр, який був начальником синагоги; і, припавши до ніг Ісусових, благав Його увійти до нього в дім;","бо у нього була єдина дочка років дванадцяти, і та помирала. Коли ж Він йшов, народ тиснув Його.","І жінка, що дванадцять років страждала на кровотечу, витратила на лікарів усе своє майно і в жодного не змогла вилікуватися.","І, підійшовши ззаду, доторкнулася до краю одежі Його; і вмить кровотеча у неї зупинилась.","І сказав Ісус: хто доторкнувся до Мене? Коли ж усі відмовлялися, Петро і ті, що були з Ним, сказали: Наставнику, народ оточує Тебе і тисне, — а Ти говориш: хто доторкнувся до Мене?","Ісус же сказав: хтось доторкнувся до Мене, бо Я відчув, як сила вийшла з Мене.","Жінка, побачивши, що вона не втаїлася, тремтячи, підійшла і, впавши перед Ним, розповіла Йому перед усім народом, з якої причини доторкнулася до Нього і як раптом зцілилася.","Він сказав їй: дерзай, дочко! Віра твоя спасла тебе, іди з миром!","Коли Він ще говорив це, приходить один з дому начальника синагоги і говорить йому: твоя дочка вмерла, не турбуй Учителя.","Ісус же, почувши це, сказав йому: не бійся, тільки віруй, і спасенна буде.","Прийшовши в дім, не дозволив увійти нікому, крім Петра, Іоана і Якова та батька і матері тієї дівчини.","Всі плакали і ридали за нею. А Він сказав: не плачте, вона не вмерла, але спить.","І глузували з Нього, знаючи, що вона вмерла.","Він же, виславши всіх геть, узяв її за руку і виголосив: дівчино, встань.","І повернувся дух її, і воскресла вмить, і Він звелів дати їй їсти.","І здивувалися батьки її. Він же повелів їм нікому не казати про те, що сталося."],"x":{"2":"51.15.40|51.16.9","4":"50.13.2-3|51.4.1-2","10":"31.6.9-10|50.13.14|51.4.12|53.12.40","12":"50.13.19|51.4.15","13":"36.33.31","14":"50.13.22|51.4.18|51.10.23|52.18.23|71.6.9","16":"50.5.15|51.4.21|52.11.33","17":"24.12.22|50.10.26|52.12.2","18":"50.13.12|50.25.29|51.4.25","19":"50.12.46|51.3.31","22":"50.8.23|51.4.35","25":"24.26.12|25.88.10","26":"50.8.28|51.5.1","41":"50.9.18|51.5.22","45":"51.5.30","49":"51.5.35"}},{"v":["Скликавши дванадцятьох, Ісус дав їм силу і владу над усіма бісами і зціляти від недуг.","І послав їх проповідувати Царство Боже та зціляти хворих.","І сказав їм: нічого не беріть на дорогу: ні палиці, ні торби, ні хліба, ні срібла, і не майте по дві одежі.","І в який дім увійдете, там залишайтесь і звідтіля виходьте в дорогу.","А якщо де не приймуть вас, то, виходячи з того міста, обтрусіть і порох з ніг ваших на свідчення проти них.","Вони вийшли і проходили по селах, благовістячи і зціляючи повсюди.","Почув Ірод четвертовладник про все, що діялося через Нього, і стривожився, бо одні говорили, що то Іоан повстав з мертвих;","інші ж — що Ілля з’явився, а ще інші, що воскрес один з давніх пророків.","І сказав Ірод: Іоанові я відсік голову; хто ж Цей, про Кого я таке чую? І намагався побачити Його.","Апостоли, повернувшись, розповіли Йому, що вони зробили. І Він, взявши їх з Собою, відійшов осібно в безлюдне місце біля міста, що зветься Вифсаїда.","Але люди, довідавшись, пішли за Ним; і Він, прийнявши їх, говорив їм про Царство Боже і зціляв тих, хто потребував зцілення.","День же почав схилятись. І приступивши до Нього, дванадцять сказали Йому: відпусти людей, щоб вони пішли в навколишні села і селища ночувати і знайти їжу, бо ми тут у безлюдному місці.","А Він сказав їм: ви дайте їм їсти. Вони сказали: нема в нас нічого, крім п’яти хлібів та двох рибин; хіба піти нам та купити їжі для всіх цих людей?","Бо їх було близько п’яти тисяч мужів. Але Він сказав ученикам Своїм: розсадіть їх рядами по п’ятдесят.","І зробили так, і розсадили всіх.","Він же, узявши п’ять хлібів і дві рибини і поглянувши на небо, благословив їх, переломив і дав ученикам, щоб роздали народові.","І всі їли, і наситились, і набрали залишків дванадцять кошиків.","І сталося, коли Він молився у безлюдному місці, ученики були з Ним. Він запитав їх: за кого вважає Мене народ?","Вони сказали у відповідь: за Іоана Хрестителя, а інші за Іллю; а ще інші говорять, що воскрес один з давніх пророків.","Він же спитав їх: а ви за кого Мене вважаєте? Петро відповів: за Христа Божого.","Він же суворо наказав їм нікому не говорити про це,","сказавши, що Синові Людському належить багато постраждати, бути зневаженим старійшинами, первосвящениками і книжниками, і бути вбитим, і на третій день воскреснути.","До всіх же сказав: якщо хто хоче йти за Мною, нехай зречеться себе, візьме хрест свій та йде за Мною.","Бо хто хоче зберегти свою душу, той погубить її, а хто погубить душу свою заради Мене, той збереже її.","Бо що за користь матиме людина, якщо придбає ввесь світ, себе ж саму згубить чи занапастить?","Бо хто посоромиться Мене і слів Моїх, того й Син Людський посоромиться, коли прийде у славі Своїй, і Отця, і святих ангелів.","Воістину кажу вам: є деякі з присутніх тут, які не зазнають смерти, доки не побачать Царство Боже.","Після цих слів, днів через вісім, узявши Петра, Іоана і Якова, зійшов Він на гору помолитись.","І коли Він молився, вигляд лиця Його змінився, і одяг Його зробився білим, блискучим.","І ось два мужі розмовляли з Ним, то були Мойсей і Ілля:","з’явившись у славі, вони говорили про кінець Його, який Йому належить завершити в Єрусалимі.","Петро ж і ті, що були з Ним, зморені були сном; але, прокинувшись, побачили славу Його і двох мужів, які стояли з Ним.","Коли вони відійшли від Нього, Петро сказав Ісусові: Наставнику, добре нам тут бути; поставимо три намети: Тобі один, Мойсеєві один і один Іллі, — не знаючи сам, що говорить.","Коли ж він це говорив, з’явилася хмара і покрила їх, і вони злякались, як увійшли в хмару.","І був з хмари Голос, Який говорив: Цей є Син Мій Улюблений; Його слухайте!","І коли був цей Голос, Ісус залишився один. А вони промовчали і нікому нічого не розповідали в ті дні про те, що бачили.","Наступного дня, як зійшли вони з гори, зустріло Його багато народу.","Раптом хтось з народу викликнув: Учителю, благаю Тебе, зглянься на сина мого, бо він у мене єдиний:","його хапає дух, і він зненацька скрикує, і трясе його так, що він пускає піну; і ледве відходить від нього, змучивши його.","Я просив учеників Твоїх, щоб вигнали його; та вони не змогли.","Ісус же сказав у відповідь: о роде невірний і розбещений! Доки буду з вами і терпітиму вас? Приведи до Мене сина твого.","Коли ж той ще йшов, біс звалив його і стряс, але Ісус заборонив нечистому духові і зцілив отрока, і віддав його батькові його.","І всі дивувались величі Божій. Коли всі ще дивувались усьому, що творив Ісус, Він сказав ученикам Своїм:","вкладіть у вуха ваші ці слова: Син Людський має бути виданий в руки людські.","Вони ж не зрозуміли слова цього, і воно було закрите від них, так що вони не збагнули його, а запитати Його про це слово боялись.","Спало ж їм на думку — хто б з них був більший?","Ісус же, знаючи думку серця їхнього, взяв дитину і поставив її перед Собою","і сказав їм: хто прийме оце дитя в ім’я Моє, той Мене приймає; і хто приймає Мене, той приймає Того, Хто послав Мене; бо хто найменший між вами, той є великий.","При цьому Іоан сказав: Наставнику, ми бачили чоловіка, який іменем Твоїм виганяє бісів, і заборонили йому, бо він не ходить з нами.","Ісус сказав йому: не забороняйте; бо хто не проти вас, той за вас.","І було, коли наближалися дні відходу Його з цього світу, Він твердо вирішив іти до Єрусалима.","І послав вісників перед лицем Своїм; і вони пішли, і увійшли до села самарянського, щоб приготувати Йому.","Але там не прийняли Його, бо було видно, що йде Він до Єрусалима.","Побачивши це, ученики Його, Яків і Іоан, сказали: Господи, хочеш, ми скажемо, щоб вогонь зійшов з неба і спалив їх, як і Ілля вчинив?","Але Він, обернувшись до них, заборонив їм і сказав: не знаєте, якого ви духу;","бо Син Людський прийшов не губити душі людські, а спасати. І пішли до іншого села.","Сталось, що коли вони були в дорозі, хтось сказав Йому: Господи! Я піду за Тобою, куди б Ти не пішов.","Ісус сказав йому: лисиці мають нори, і птахи небесні — гнізда; а Син Людський не має, де й голови прихилити.","А іншому сказав: іди за Мною. Той сказав: Господи, дозволь мені перше піти і поховати батька мого.","Але Ісус сказав йому: залиш мертвим ховати своїх мерців; а ти йди, благовісти Царство Боже.","І ще інший сказав: я піду за Тобою, Господи, тільки дозволь перше мені попрощатися з домашніми моїми.","Але Ісус сказав йому: жоден, хто поклав руку свою на рало і озирається назад, не придатний для Царства Божого."],"x":{"1":"50.10.1|51.3.13|51.6.7","5":"50.10.14|51.6.11|54.13.51","7":"50.14.1|51.6.14","9":"52.23.8","10":"50.14.13|51.6.32","13":"50.14.17|51.6.38|53.6.9","18":"50.16.13|51.8.27","20":"53.6.69","22":"50.17.22","23":"50.10.38|50.16.24|51.8.34|52.14.27","25":"50.16.26|51.8.36","26":"50.20.33|51.8.38|52.12.9|72.2.12","28":"50.17.1|51.9.3","31":"52.22.37","32":"57.1.16","35":"4.18.15|50.3.17|50.17.5","38":"50.17.14|51.9.17","44":"50.17.22|51.9.31","45":"52.2.50","46":"50.18.1|51.9.33","48":"50.10.40|50.18.5|51.9.37|69.4.8","49":"51.9.38","50":"67.1.18","51":"51.16.19|54.1.2","53":"53.4.9","54":"11.1.10:12","56":"50.18.11|53.3.17","57":"50.8.19","60":"50.8.22"}},{"v":["Після того обрав Господь і інших сімдесят учеників і послав їх по двоє перед Собою до кожного міста і місцевості, куди Сам хотів іти.","І сказав їм: жниво велике, а женців мало; тож благайте Господаря жнива, щоб вислав женців на жниво Своє.","Ідіть! Я посилаю вас, як ягнят між вовків.","Не беріть ні мішка, ні торби, ні взуття, і нікого в дорозі не вітайте.","В який дім увійдете, спочатку кажіть: мир дому цьому.","І якщо буде там син миру, то спочине на ньому мир ваш, а коли ні, то до вас повернеться.","В тому ж домі перебувайте, їжте і пийте те, що в них є, бо робітник вартий винагороди своєї. Не переходьте з дому в дім.","І в яке тільки місто прийдете і приймуть вас, їжте, що вам подадуть.","І зціляйте недужих, що знаходяться в ньому, і кажіть їм: наблизилось до вас Царство Боже.","Якщо ж прийдете в якесь місто і не приймуть вас, то, вийшовши на перехрестя його, скажіть:","і порох, що прилип до нас з вашого міста, обтрушуємо вам; але знайте, що наблизилося до вас Царство Боже.","Кажу ж вам, що содомлянам у день той відрадніше буде, ніж місту тому.","Горе тобі, Хоразине, горе тобі, Вифсаїдо, бо якби у Тирі та Сидоні сталися ті чудеса, які були у вас, то давно б вони, сидячи у веретищі й попелі, покаялися.","Однак Тиру і Сидону відрадніше буде на суді, ніж вам.","І ти, Капернауме, що піднісся до неба, до пекла зійдеш.","Хто слухає вас, той Мене слухає, і хто зневажає вас, той Мене зневажає, а хто зневажає Мене, той зневажає Того, Хто послав Мене.","Сімдесят учеників повернулися з радістю і говорили: Господи, і біси коряться нам в ім’я Твоє.","Він же сказав їм: Я бачив сатану, що, як блискавка, впав з неба.","Ось даю вам владу наступати на змій, і на скорпіонів, і на всяку силу вражу; і ніщо не зашкодить вам.","Однак тому не радійте, що духи вам коряться; а радійте тому, що імена ваші записані на небесах.","У той час зрадів духом Ісус і сказав: славлю Тебе, Отче, Господи неба і землі, що Ти утаїв це від премудрих та розумних і відкрив те дітям. Так, Отче, бо таке було Твоє благовоління.","І, звернувшись до учеників, сказав: усе передав Мені Отець Мій; і ніхто не знає, хто є Син, тільки Отець; і хто є Отець, знає тільки Син і той, кому Син хоче відкрити.","І, звернувшись до учеників, сказав їм осібно: блаженні очі, які бачать те, що ви бачите!","Бо кажу вам, багато пророків і царів бажали б бачити те, що ви бачите, та й не побачили, і чути, що ви чуєте, та й не почули.","І ось один законник встав і, спокушаючи Його, сказав: Учителю, що зробити мені, щоб успадкувати життя вічне?","Він же сказав йому: в законі що написано? Як читаєш?","Він сказав у відповідь: люби Господа Бога твого всім серцем твоїм, і всією душею твоєю, і всією силою твоєю, і всім розумом твоїм, і ближнього твого — як самого себе.","Ісус сказав йому: правильно ти відповідав; так роби — і будеш жити.","Він же, бажаючи виправдати себе, сказав Ісусові: а хто ж мій ближній?","На це Ісус сказав: один чоловік ішов з Єрусалима до Єрихона і потрапив до рук розбійників, які зняли з нього одяг, поранили його і відійшли, залишивши його ледве живого.","Випадково один священик проходив тією дорогою і, побачивши його, пройшов мимо.","Так само і левит, що був на тому місці, підійшов, подивився і пройшов мимо.","Якийсь же самарянин, проїжджаючи, натрапив на нього і, побачивши його, змилосердився;","і, підійшовши, перев’язав йому рани, поливши оливою і вином; і, посадивши його на свого осла, привіз його до заїжджого двору і потурбувався про нього;","а на другий день, відходячи, вийняв два динарії, дав господареві заїжджого двору і сказав йому: подбай про нього; і якщо витратиш на нього більше, я, коли повертатимусь, віддам тобі.","Отже, кого з тих трьох вважаєш ти ближнім того, хто потрапив до рук розбійників?","Він сказав: того, який змилосердився над ним. Тоді Ісус сказав йому: іди і ти роби так само.","Коли вони йшли, прийшов Він до одного села; тут жінка на ім’я Марфа прийняла Його у свій дім.","У неї була сестра, що звалася Марією, котра сіла біля ніг Ісуса і слухала слово Його.","Марфа ж клопоталася про велике частування і, підійшовши, сказала: Господи, чи Тобі байдуже, що сестра моя покинула мене одну слугувати? Скажи їй, щоб допомогла мені.","Ісус же сказав їй у відповідь: Марфо! Марфо! Ти турбуєшся і клопочешся про багато що.","А потрібне ж тільки одне; Марія ж благу обрала частку, яка не відніметься від неї."],"x":{"2":"50.9.37|53.4.35","3":"50.10.16","4":"11.4.29|50.10.10","5":"50.10.12|51.6.10","7":"4.24.14|50.10.10|71.5.18","11":"50.10.14|54.13.51","12":"50.11.24","13":"31.23.1|36.3.6|36.26.2|50.11.21","16":"3.16.11|50.10.40|52.9.48|53.13.20","19":"25.90.13|58.2.13","20":"31.4.3|37.12.1|67.4.3","21":"31.32.4|50.11.25|63.1.21|64.4.3","23":"50.13.16","24":"56.1.10","25":"50.22.35|51.12.28","27":"2.19.18|4.6.5|50.22.37|51.12.29","28":"2.18.5","31":"54.10.28","38":"53.11.1|53.12.2"}},{"v":["І сталося, коли в одному місці Він молився і перестав, один з учеників Його сказав Йому: Господи! Навчи нас молитися, як і Іоан навчив учнів своїх.","Він сказав їм: коли молитесь, говоріть: Отче наш, що єси на небесах, нехай святиться ім’я Твоє; нехай прийде Царство Твоє; нехай буде воля Твоя, як на небі, так і на землі.","Хліб наш насущний дай нам сьогодні;","і прости нам провини наші, як і ми прощаємо винуватцям нашим; і не введи нас у спокусу, але визволи нас від лукавого.","І сказав їм: припустімо, що хто-небудь з вас, маючи друга, прийде до нього опівночі і скаже йому: друже! Позич мені три хліби,","бо друг мій зайшов до мене з дороги, і я не маю чого дати йому.","А той зсередини скаже у відповідь: не турбуй мене, двері вже зачинені, і діти мої зі мною на постелі; не можу встати і дати тобі.","Кажу ж вам, якщо він не встане і не дасть йому по дружбі з ним, то через невідступність його, вставши, дасть йому, скільки той просить.","І я скажу вам: просіть, і дасться вам, шукайте, і знайдете; стукайте, і відчинять вам,","бо кожний, хто просить, одержує, хто шукає, знаходить, хто стукає, тому відчиняють.","Який з вас, батьків, коли син попросить у нього хліба, подасть йому камінь? Або, коли попросить риби, подасть йому змію замість риби?","Або, якщо попросить яйця, подасть йому скорпіона?","Отже, якщо ви, будучи злими, вмієте добрі дари давати дітям вашим, то тим більше Отець Небесний дасть Духа Святого тим, хто просить у Нього.","Одного разу вигнав Він біса, який був німий; і коли біс вийшов, німий заговорив; і народ дивувався.","Деякі ж з них говорили: Він виганяє бісів силою Вельзевула, князя бісівського.","А інші, спокушаючи, домагалися від Нього знамення з неба.","Але Він, знаючи їхні думки, сказав їм: всяке царство, що само в собі розділиться, запустіє; і дім, який розділиться сам в собі, упаде.","Якщо ж сатана сам у собі розділився, то як устоїть його царство? А ви говорите, що Я силою Вельзевула виганяю бісів.","Якщо ж Я силою Вельзевула виганяю бісів, то сини ваші чиєю силою виганяють їх? Тому вони будуть вам суддями.","Якщо ж Я перстом Божим виганяю бісів, то, значить, прийшло до вас Царство Боже.","Коли сильний, озброївшись, стереже свій дім, тоді майно його в безпеці;","коли ж сильніший за нього нападе і переможе його, тоді візьме всю зброю його, на яку він покладався, і здобич свою роздасть.","Хто не зі Мною, той проти Мене; і хто не збирає зі Мною, той розкидає.","Коли нечистий дух вийде з людини, то ходить місцями безводними, шукаючи спокою, і, не знаходячи, каже: повернусь у дім свій, звідки вийшов;","і, прийшовши, знаходить його виметеним і прибраним.","Тоді йде і бере з собою інших сім духів, ще лютіших за себе, і, увійшовши, живуть там, — і буває для людини тієї останнє гіршим за перше.","Коли ж він це говорив, одна жінка з натовпу, піднісши голос, сказала Йому: блаженна утроба, що носила Тебе, і груди, що годували Тебе!","А Він сказав: блаженні ті, що слухають слово Боже і виконують його.","Коли ж багато народу стало збиратися, Він почав говорити: рід цей лукавий — він знамення шукає, і знамення не дасться йому, крім знамення Іони пророка.","Бо як Іона був знаменням ниневитянам, так буде і Син Людський родові цьому.","Цариця південна постане на суд з людьми роду цього і осудить їх, бо вона від краю землі прийшла послухати мудрість Соломонову; а ось тут Більший від Соломона.","Ниневитяни постануть на суд з родом цим і осудять його, бо вони покаялися після проповіді Іониної, а ось тут Більший від Іони.","Ніхто, засвітивши світильник, не ставить його в закритому місці чи під посудину, але на свічник, щоб усі, що входять, бачили світло.","Світильником тіла є око; отже, якщо око твоє буде чистим, то і все тіло твоє буде світлим; а якщо воно буде нечистим, то і тіло твоє буде темним.","Отже, дивись, щоб світло, яке в тобі, не стало темрявою.","Якщо ж тіло твоє все світле і немає жодної темної частини, то буде світле все так, ніби світильник сяйвом освітлює тебе.","Коли Він говорив це, один фарисей запросив Його до себе на обід. Він прийшов і возліг.","Фарисей же здивувався, побачивши, що Він не вимив рук перед обідом.","Але Господь сказав йому: нині ви, фарисеї, очищаєте зовні чашу і блюдо, а нутро ваше сповнене злодійства та лукавства.","Нерозумні! Чи не Той, Хто створив зовнішнє, створив і внутрішнє?","Краще подавайте милостиню з того, що маєте, тоді все буде у вас чисте.","Але горе вам, фарисеям, що даєте десяту частину з м’яти, рути і з усякого зілля, а не дбаєте про суд і любов Божу: і це належить робити, і того не залишати.","Горе вам, фарисеям, що любите перші місця в синагогах і привітання на торжищах.","Горе вам, книжники і фарисеї, лицеміри, що ви — як ті невідомі гроби, поверх яких люди ходять і не знають того.","На це хтось із законників сказав Йому: Учителю, говорячи це, Ти і нас ображаєш.","Але Він сказав: і вам, законникам, горе, бо накладаєте на людей тягарі, які важко носити, самі ж жодним пальцем своїм не доторкнетесь до них.","Горе вам, що будуєте гробниці пророкам, яких повбивали батьки ваші:","цим ви свідчите і схвалюєте діла батьків ваших, і погоджуєтеся з ними, бо ті повбивали пророків, ви ж будуєте їм гробниці.","Тому і премудрість Божа сказала: пошлю до них пророків і апостолів, і декого з них уб’ють, а декого виженуть.","Хай же буде покараний рід цей за кров усіх пророків, пролиту від створення світу,","від крови Авеля до крови Захарії, вбитого між жертовником і храмом. Так, кажу вам, стягнеться з роду цього.","Горе вам, законникам, що ви взяли ключ розуміння: самі не ввійшли і тим, хто хотів увійти, боронили.","Коли Він говорив їм це, книжники і фарисеї почали дуже нападати на Нього, запитуючи багато про що,","підкопуючись під Нього і намагаючись уловити з уст Його що-небудь таке, щоб звинуватити Його."],"x":{"2":"50.6.9","3":"26.30.8","4":"56.5.8|57.2.9|63.10.13","9":"50.7.7|50.21.22|51.11.24|53.14.13|55.1.6","11":"50.7.9","13":"75.12.9","14":"50.9.32|50.12.22","15":"50.9.34|50.12.24|51.3.22","16":"63.1.22","17":"50.12.25|51.3.24","20":"1.8.19|37.2.44","24":"50.12.43","26":"57.2.20|75.6.4|75.10.26","27":"52.1.48","29":"42.2.1|50.12.39","31":"10.10.1:4|13.9.1|50.12.42","32":"42.3.5|50.12.41","33":"50.5.15|51.4.21","34":"50.6.22","38":"51.7.3","39":"50.23.25","41":"31.58.7|37.4.24","42":"50.23.23","43":"50.23.6-7|51.12.38-39|52.20.46","46":"50.23.4|54.15.10","49":"13.36.15|17.9.26|50.23.34"}},{"v":["Тим часом, коли зібралися тисячі народу, так що тиснули один одного, Він почав говорити, передусім ученикам Своїм: бережіться закваски фарисейської, яка є лицемірство.","Немає нічого прихованого, що не відкрилося б, і таємного, про що б не дізналися.","Тому те, що ви сказали у пітьмі, почується при світлі; і що говорили на вухо в домах, те буде проголошене на покрівлях.","Кажу ж вам, друзям Моїм: не бійтеся тих, що вбивають тіло і потім нічого більше зробити не можуть,","але скажу вам, кого боятися: бійтеся того, хто має владу після вбиття вкинути в геєну вогненну; так, кажу вам, того бійтеся.","Чи не п’ять малих птахів продаються за два асарія? І жоден з них не забутий Богом.","А у вас і волосся на голові все перелічене. Отже, не бійтеся; ви дорожчі за багатьох малих птахів.","Кажу ж вам: кожного, хто визнає Мене перед людьми, і Син Людський визнає перед ангелами Божими;","а хто зречеться Мене перед людьми, той відкинутий буде перед ангелами Божими.","І кожному, хто скаже слово на Сина Людського, проститься; а хто Святого Духа хулитиме, тому не проститься.","Коли ж приведуть вас у синагоги, до правителів і володарів, не турбуйтесь, як і що відповідати або що говорити,","бо в той час Святий Дух навчить вас, що треба говорити.","Хтось з народу сказав Йому: Учителю, скажи братові моєму, щоб він розділив спадщину зі мною!","Він же сказав чоловікові тому: хто настановив Мене судити чи ділити вас?","При цьому сказав їм: глядіть, остерігайтеся користолюбства, бо життя людини не залежить від багатства її маєтку.","І сказав їм притчу: в одного багатого чоловіка добре вродила нива.","І міркував він сам собі: що мені робити? Немає куди мені зібрати плодів моїх.","І сказав: ось що зроблю — зруйную житниці мої та збудую більші, і зберу туди весь хліб мій і все добро моє.","І скажу душі моїй: душе, багато маєш добра, що лежить у тебе на багато років: спочивай, їж, пий, веселись.","Але Бог сказав йому: нерозумний! Цієї ночі душу твою візьмуть у тебе; кому ж дістанеться те, що ти наготував?","Так буває з тим, хто збирає скарби для себе, а не в Бога багатіє.","Сказав же ученикам Своїм: тому кажу вам, — не піклуйтесь про душу вашу, що вам їсти, ні про тіло ваше, — у що вдягнетеся.","Душа більша за їжу, і тіло — за одяг.","Погляньте на воронів: вони не сіють, не жнуть; у них немає ні комор, ні житниць, і Бог годує їх; наскільки ж ви кращі за птахів!","Та й хто з вас, піклуючись, може додати собі зросту хоч на один лікоть?","Отже, якщо і найменшого зробити не можете, чого піклуєтесь про інше?","Погляньте на лілеї, як вони ростуть: не трудяться, не прядуть. Кажу ж вам, що й Соломон у всій славі своїй не одягався так, як одна з них.","Коли ж траву на полі, яка сьогодні є, а завтра буде кинута у піч, Бог так одягає, то наскільки краще вас, маловіри!","Отже, не шукайте, що вам їсти або що пити, і не турбуйтесь,","бо всього того шукають люди світу цього, ваш же Отець знає, чого потребуєте.","Краще шукайте Царства Божого, а те все додасться вам.","Не бійся, мале стадо! Бо Отець ваш благозволив дати вам Царство.","Продайте майно ваше і роздайте милостиню. Зробіть собі гамани, що не старіють, і скарб, що не зменшується на небесах, куди злодій не наближається і де міль не точить.","Бо де скарб ваш, там і серце ваше буде.","Нехай будуть стегна ваші підперезані і світильники засвічені.","І ви будьте подібні до людей, які чекають повернення господаря свого з весілля, щоб, коли прийде і постукає, негайно відчинити йому.","Блаженні ті раби, господар яких, прийшовши, знайде, що пильнують вони. Істинно говорю вам, що він підпережеться і посадить їх та, підійшовши, послужить їм.","І якщо прийде у другу сторожу, і в третю сторожу прийде, і знайде їх так, то блаженні ті раби.","Знайте, що, коли б відав господар дому о якій годині прийде злодій, то пильнував би і не дав би підкопати дому свого.","Будьте ж і ви готові, бо в яку годину і не гадаєте, прийде Син Людський.","Тоді сказав Йому Петро: Господи, нам притчу цю говориш чи всім?","Господь же сказав: хто вірний і мудрий управитель, якого господар поставив над слугами своїми роздавати їм своєчасно міру хліба?","Блаженний раб той, господар якого, прийшовши, знайде, що він чинить так.","Істинно кажу вам: над усім маєтком своїм поставить його.","Якщо ж раб той в серці своїм скаже: не скоро господар мій прийде, і почне бити слуг та служниць, їсти і пити та упиватися, —","то прийде господар раба того у день, коли він не сподівається, і в годину, якої не відає, і розітне його, і визначить йому долю з невірними.","Раб же той, який знав волю господаря свого, та не був готовий і не робив за волею його, буде багато битий.","А той, хто не знав і зробив щось гідне покарання, буде битий менше. Від усякого, кому дано багато, багато й вимагається, і кому багато довірено, з того більше й спитають.","Я прийшов вогонь звести на землю, і як хотів би, щоб він уже запалав!","Хрещенням маю Я хреститися; і як Я втримаюся, поки це здійсниться!","Чи думаєте ви, що Я прийшов дати мир землі? Ні, кажу вам, а розділення.","Бо віднині п’ятеро в одному домі розділені: троє проти двох, і двоє проти трьох.","Розділиться батько з сином, і син з батьком; мати з дочкою, і дочка з матір’ю; свекруха з невісткою своєю, і невістка з свекрухою своєю.","Сказав же і до народу: коли ви побачите хмару, що йде із заходу, то відразу говорите: дощ буде, і буває так.","І коли віє південний вітер, говорите: спека буде, і буває.","Лицеміри! Лице неба і землі розпізнавати умієте; як же час цей не розпізнаєте?","Чому ж ви і по собі не судите, що є справедливе?","Коли ти йдеш з супротивником своїм до правителя, то дорогою подбай, щоб звільнитися від нього, щоб він не притяг тебе до судді, а суддя не віддав тебе слузі, а слуга не посадив би тебе до в’язниці.","Кажу тобі: не вийдеш звідти, аж поки не віддаси й останнього гроша."],"x":{"1":"50.16.6|51.8.15","2":"50.10.26|51.4.22|52.8.17","4":"31.8.12|31.51.7|32.1.8|50.10.28","6":"50.10.29","7":"52.21.18","8":"50.10.32","9":"51.8.38|52.9.26|72.2.12","10":"50.12.31|51.3.28|58.5.16","11":"50.10.19|51.13.11","15":"51.4.19|71.6.9","19":"30.11.17|63.15.32","20":"24.20.22|25.38.7|32.17.11","21":"50.6.20|71.6.19","22":"25.54.23|50.6.25|56.5.7","24":"25.103.27-28","31":"50.6.33|51.10.30","33":"50.6.20","35":"56.1.13|66.3.16","39":"50.24.43|57.3.10|69.5.2|76.16.15","42":"50.24.45","47":"53.15.22","50":"50.20.22","51":"50.10.34","53":"43.7.6","54":"50.16.2","58":"50.5.25"}},{"v":["У той час деякі прийшли і розповіли про галилеян, кров яких Пилат змішав з жертвами їхніми.","У відповідь Ісус сказав їм: чи думаєте ви, що ці галилеяни були грішніші за всіх галилеян, що так постраждали?","Ні, кажу вам; але, якщо не покаєтесь, усі так само загинете.","Або думаєте, що ті вісімнадцять, на яких упала башта Силоамська і побила їх, були винні більше за всіх, що живуть в Єрусалимі?","Ні, кажу вам; але, якщо не покаєтесь, усі так само загинете.","І сказав оцю притчу: один чоловік мав у своєму винограднику посаджену смоковницю, і прийшов шукати плоду на ній і не знайшов.","І сказав виноградареві: ось третій рік я приходжу шукати плоду на цій смоковниці і не знаходжу; зрубай її, навіщо вона і землю займає?","Але той сказав йому у відповідь: господарю, залиш її і на цей рік, поки я обкопаю її і підсиплю гноєм.","Можливо, дасть вона плід; а якщо ні, наступного року зрубаєш її.","В одній із синагог Він навчав у суботу.","Там була жінка, що мала духа немочі років вісімнадцять: вона була скорчена і ніяк не могла випростатись.","Ісус, побачивши її, покликав і сказав їй: жінко, ти звільнена від твоєї недуги.","І поклав на неї руки; і вона зараз же випросталась і почала славити Бога.","При цьому начальник синагоги, обурюючись, що Ісус зцілив її в суботу, сказав народові: є шість днів, в які дозволено робити; в ті і приходьте зцілятися, а не в день суботній.","Господь сказав йому у відповідь: лицеміре, чи не відв’язує кожний з вас у суботу вола свого або осла від ясел і не веде напувати?","А цю дочку Авраамову, яку зв’язав сатана ось уже вісімнадцятий рік, чи не належало визволити від цих пут у день суботній?","І коли Він говорив це, усі, що противилися Йому, засоромились; і всі люди раділи всім славним ділам Його.","Він же сказав: до чого подібне Царство Боже, і до чого уподібню його?","Воно подібне до зерна гірчичного, яке чоловік взяв і посадив у своєму саду; і виросло, і стало великим деревом, і птахи небесні оселилися у гілках його.","Ще сказав: до чого уподібню Царство Боже?","Воно подібне до закваски, яку жінка, взявши, поклала на три міри борошна, аж доки не вкисне все.","І проходив через міста і села, і навчав, прямуючи до Єрусалима.","Один чоловік сказав Йому: Господи, невже мало таких, що спасаються? А Він сказав їм:","намагайтеся увійти через вузькі ворота, бо, кажу вам, багато буде таких, які намагатимуться увійти, і не зможуть.","Коли Господар дому встане і зачинить двері, тоді ви, стоячи зовні, почнете стукати у двері і говорити: Господи! Господи! Відчини нам. А Він скаже вам у відповідь: не знаю вас, звідки ви.","Тоді почнете говорити: ми їли і пили перед Тобою, і на перехрестях наших Ти навчав.","А Він скаже: говорю вам, що не знаю вас, звідки ви; відійдіть від Мене всі, хто чинить неправду.","Там буде плач і скрегіт зубів, коли побачите Авраама, Ісаака і Якова і всіх пророків у Царстві Божому, а себе — вигнаними геть.","І прийдуть від сходу і заходу, від півночі й півдня, і возляжуть у Царстві Божому.","І ось є останні, що будуть першими, і є перші, що будуть останніми.","У той день прийшли деякі з фарисеїв і сказали Йому: вийди і піди звідси, бо Ірод хоче Тебе вбити.","І сказав їм: підіть і скажіть отій лисиці: ось виганяю бісів і зціляю сьогодні і завтра, і на третій день закінчу.","А втім, мені треба ходити сьогодні, завтра і в наступний день, бо неможливо, щоб пророк загинув поза Єрусалимом.","Єрусалиме, Єрусалиме, що вбивав пророків і камінням побив посланих до тебе! Скільки разів хотів Я зібрати дітей твоїх, як птах пташенят своїх під крила, і ви не захотіли!","Ось залишається вам дім ваш порожнім. Кажу ж вам, що ви не побачите Мене, доки не прийде час, коли скажете: благословенний, Хто гряде в ім’я Господнє!"],"x":{"6":"31.5.2","7":"50.21.19","14":"1.20.9","18":"50.13.31|51.4.30","20":"50.13.33","22":"50.9.35|51.6.6","24":"50.7.13","25":"50.7.23|50.25.10|52.6.46","27":"25.6.9|50.25.41|63.8.3|72.2.19","29":"0.28.14|31.2.3|31.49.6|31.60.3|49.1.11","30":"50.19.30|51.10.31|54.10.45|54.28.28","34":"50.23.37"}},{"v":["Довелось Йому в суботу ввійти в дім одного з начальників фарисейських спожити хліба, і вони стежили за Ним.","І ось став перед Ним чоловік, який страждав на водяну хворобу.","Тоді Ісус запитав законників і фарисеїв: чи дозволено зціляти в суботу?","Вони промовчали. А Він, доторкнувшись, зцілив його і відпустив.","При цьому сказав їм: якщо у кого з вас осел або віл упаде в колодязь, чи не одразу ж витягнете його і в день суботній?","І не змогли відповісти Йому на це.","Помітивши ж, як запрошені вибирали перші місця, сказав їм притчу:","коли будеш запрошений кимось на весілля, не сідай на перше місце, щоб не знайшовся хто між запрошеними поважніший за тебе,","і щоб той, хто запросив тебе і його, підійшовши, не сказав тобі, щоб поступився цьому місцем, і тоді доведеться тобі з соромом зайняти останнє місце.","Але коли будеш запрошений, то, прийшовши, сідай на останнє місце, щоб той, хто запросив тебе, підійшовши, сказав тобі: друже, пересядь вище. Тоді буде тобі честь перед тими, хто сидить з тобою.","Бо всякий, хто підноситься, буде принижений, а хто принижує себе, піднесеться.","Сказав же і тому, хто запросив Його: коли справляєш обід або вечерю, не клич друзів твоїх, ні братів твоїх, ні родичів твоїх, ні сусідів багатих, щоб і вони тебе колись не запросили і не одержав ти відплати.","Але, коли справляєш званий обід, клич убогих, калік, кривих, сліпих,","і блаженний будеш, бо вони не мають чим віддати тобі; віддасться ж тобі у воскресіння праведних.","Почувши це, один з тих, що возлежали з Ним, сказав Йому: блаженний, хто споживатиме хліб у Царстві Божому!","Він же сказав йому: один чоловік справляв велику вечерю і запросив багатьох.","І коли настав час вечері, послав раба свого сказати запрошеним: ідіть, бо все вже готове.","І почали всі, ніби змовившись, вибачатися. Перший сказав йому: я купив землю і мені треба піти і оглянути її; прошу тебе, вибач мені.","Другий сказав: я купив п’ять пар волів та йду випробувати їх; прошу тебе, вибач мені.","Третій сказав: я одружився і через те не можу прийти.","І, повернувшись, раб той розповів про це господареві своєму. Тоді, розгнівавшись, господар сказав рабові своєму: піди швидше на вулиці й провулки міста і приведи сюди вбогих, калік, сліпих і кривих.","І сказав раб: господарю, зроблено, як ти велів, і ще є місце.","Господар сказав рабові: піди на дороги і загороди і умовляй прийти, щоб наповнився дім мій.","Бо кажу вам, що ніхто з тих запрошених не покуштує моєї вечері, бо багато званих, та мало обраних.","З Ним ішло багато народу, і, обернувшись, Він сказав їм:","коли хто приходить до Мене і не зненавидить батька свого і матері, жінки і дітей, братів і сестер, та ще й життя свого, той не може бути Моїм учеником.","І хто не несе хрест свій і не йде слідом за Мною, той не може бути Моїм учеником.","Бо хто з вас, бажаючи будувати башту, не сяде спершу і не обчислить витрат, чи вистачить у нього коштів, щоб закінчити?","Щоб, коли закладе основу і не зможе закінчити, усі, хто побачить, не почали сміятися з нього,","кажучи: як цей чоловік почав будувати, та не зміг закінчити.","Або який цар, ідучи на війну проти іншого царя, не сяде і не порадиться спершу, чи під силу йому з десятьма тисячами встояти проти того, хто йде на нього з двадцятьма тисячами?","Якщо ж ні, то поки той ще далеко, він пошле до нього посольство просити про мир.","Так і кожний з вас, хто не зречеться усього свого майна, не може бути Моїм учеником.","Сіль — добра річ; але якщо сіль утратить силу, то чим осолиться?","Ні в землю, ні на гній не придатна; геть висипають її. Хто має вуха слухати, нехай слухає!"],"x":{"8":"26.25.6","11":"50.23.12|52.18.14","12":"18.4.7|26.3.27-28","16":"26.9.1-2|50.22.2|76.19.9","21":"50.5.3|63.1.27-28","24":"50.22.8","26":"50.10.37","27":"50.10.38|50.16.24|51.8.34|52.9.23|72.3.12","34":"50.5.13|51.9.50"}},{"v":["Всі митарі і грішники наближалися до Нього, щоб послухати Його.","І нарікали фарисеї та книжники, кажучи: Він приймає грішників і їсть з ними.","Але Він розповів їм таку притчу:","який чоловік з вас, маючи сто овець і загубивши одну з них, не залишить дев’яносто дев’ять у пустелі і не йде за загубленою, доки не знайде її?","І, знайшовши її, з радістю візьме на плечі свої.","І, прийшовши додому, скликає друзів і сусідів, кажучи їм: порадійте зі мною; я знайшов вівцю мою загублену.","Кажу вам, що так на небесах більше буде радости за одного грішника, що кається, ніж за дев’яносто дев’ять праведників, які не потребують покаяння.","Або яка жінка, маючи десять драхм*, якщо загубить одну драхму, не запалює світильник, і не замітає кімнату, і шукає старанно, доки не знайде,","а знайшовши, покличе подруг і сусідок і скаже: порадійте зі мною, бо я знайшла загублену драхму.","Такою, кажу вам, буває радість у ангелів Божих за одного грішника, що покаявся.","Ще сказав: один чоловік мав двох синів.","І сказав молодший з них батькові: батьку, дай мені частину майна, що належить мені. І батько розділив між ними майно.","Через кілька днів молодший син, зібравши все, пішов у далекий край і там розтратив своє майно, живучи розпусно.","Коли ж він усе розтратив, настав великий голод у тій країні, і він почав бідувати.","І пішов, пристав до одного з жителів тієї країни; а той послав його на свої поля пасти свиней.","І він радий був насититися стручками, які їли свині, але ніхто не давав йому.","Опам’ятавшись, він сказав: скільки наймитів у батька мого мають надлишок хліба, а я вмираю з голоду;","встану, піду до батька мого і скажу йому: батьку! Згрішив я перед небом і перед тобою","і вже недостойний зватися твоїм сином; прийми мене як одного з наймитів твоїх.","Встав і пішов до батька свого. І коли він був ще далеко, батько побачив його і переповнився жалем; побіг і, кинувшись йому на шию, цілував його.","Син же сказав йому: батьку! Я згрішив перед небом і перед тобою і вже недостойний зватися твоїм сином.","А батько сказав рабам своїм: принесіть найкращий одяг і вдягніть його, і дайте перстень на руку його і взуття на ноги;","і приведіть відгодоване теля, і заколіть; будемо їсти і веселитися!","Бо син мій оцей був мертвий і ожив, пропав і знайшовся. І почали веселитися.","А старший син його був у полі; і коли, повертаючись, наблизився до дому, почув музику та співи та радощі;","і, покликавши одного із слуг, запитав: що це таке?","Той же сказав йому: брат твій прийшов; і батько твій заколов відгодоване теля, бо прийняв його здоровим.","Він розгнівався і не схотів увійти. Батько ж його, вийшовши, кликав його.","Але він сказав у відповідь батькові: ось я стільки років служу тобі і ніколи заповіді твоєї не переступав, але ти ніколи не дав мені й козляти, щоб мені повеселитися з друзями моїми.","Коли ж цей син твій, що змарнував добро своє з блудницями, прийшов, ти заколов для нього відгодоване теля.","Він же сказав йому: сину, ти завжди зі мною, і все моє — твоє.","Веселитися ж і радіти треба тому, що брат твій оцей був мертвий і ожив, пропав і знайшовся."],"x":{"4":"50.18.12","24":"66.2.1|66.5.14|68.2.13|76.3.1"},"n":{"8":["Дрібна монета."]}},{"v":["Сказав же Господь і ученикам Своїм: один чоловік був багатий і мав управителя, на якого було донесено йому, що він марнує його майно.","І, покликавши його, сказав йому: що це я чую про тебе? Дай звіт про управительство твоє, бо ти не можеш більше управляти.","Тоді управитель сказав сам собі: що мені робити? Господар мій відбирає в мене управління домом. Копати я не можу, просити соромлюся.","Знаю, що зробити: коли буду відсторонений від управління домом, хай приймуть мене у свої доми.","І, покликавши боржників господаря свого, кожного окремо, сказав першому: скільки ти винен господареві моєму?","Він сказав: сто мір оливи. І сказав йому: візьми твою розписку і сідай скоріш, напиши: п’ятдесят.","Потім другому сказав: а ти скільки винен? Він відповів: сто мір пшениці. І сказав йому: візьми свою розписку і напиши: вісімдесят.","І похвалив господар управителя неправедного, що мудро зробив; бо сини віку цього розумніші від синів світу в роді своїм.","І Я кажу вам: здобувайте собі друзів з багатства неправедного, щоб вони, як станете вбогими, прийняли вас у вічні обителі.","Вірний у малому і у великому вірний; а неправедний у малому, неправедний і у великому.","Отже, якщо ви у неправедному багатстві не були вірні, хто ж довірить вам істинне?","І якщо в чужому не були вірні, ваше хто вам дасть?","Ніякий слуга не може служити двом господарям, бо або одного зненавидить, а другого полюбить, або до одного виявлятиме прихильність, а другого занедбає. Не можете служити Богові і мамоні*.","Чули все це і фарисеї, що були сріблолюбцями, і глузували з Нього.","Він сказав їм: ви показуєте себе праведниками перед людьми, але Бог знає серця ваші, бо що високе в людей, те мерзенне перед Богом.","Закон і Пророки були до Іоана; з цього часу Царство Боже благовіститься, і кожен із зусиллям входить у нього.","Але скоріше небо і земля перейдуть, ніж одна риска із закону загине.","Усякий, хто розведеться з жінкою своєю і одружиться з іншою, перелюбствує; і кожен, хто жениться на розведеній з чоловіком, чинить перелюб.","Один чоловік був багатий, одягався в порфиру і висон* і щодня розкішно бенкетував.","Був же один убогий на ім’я Лазар, що лежав біля воріт його весь у струпах","і бажав насититися крихтами, що падали зі столу багача; пси, приходячи, лизали струпи його.","Прийшло вмерти вбогому, і віднесений був ангелами на лоно Авраамове. Помер же і багатий, і поховали його.","І в пеклі, будучи в муках, він підняв очі свої, побачив здалеку Авраама і Лазаря на лоні його.","І,голосно закричавши, сказав: отче Аврааме, змилосердься наді мною і пошли Лазаря, нехай умочить кінець пальця свого у воду та прохолодить язик мій, бо я мучусь у полум’ї цьому.","Але Авраам сказав: чадо! Згадай, що ти одержав уже блага твої за життя твого, а Лазар — тільки зло; отже, тепер він тут тішиться, а ти страждаєш.","І, крім усього того, між нами і вами утверджена велика безодня, так що ті, які хочуть перейти звідси до вас, не зможуть, так само звідти до нас не переходять.","Тоді він сказав: так благаю тебе, отче, пошли його в дім батька мого.","Маю бо п’ятьох братів, нехай засвідчить їм, щоб і вони не прийшли в це місце муки.","Авраам сказав йому: у них є Мойсей і пророки; нехай слухають їх.","Він же сказав: ні, отче Аврааме! Але коли хто з мертвих прийде до них, покаються.","Тоді Авраам сказав йому: якщо Мойсея і пророків не слухають, то хоч би хто і з мертвих воскрес, не повірять."],"x":{"9":"50.6.19|50.19.21","10":"50.25.21","13":"50.6.24","14":"71.6.10","15":"8.16.7|32.11.20","16":"50.11.12","17":"31.40.8","18":"4.24.1|50.19.9","25":"24.21.7:13","29":"53.5.39:45"},"n":{"13":["Багатство."],"19":["Найтонша лляна тканина."]}},{"v":["Сказав також Ісус ученикам: неможливо не прийти спокусам; але горе тому, через кого вони приходять.","Краще було б йому, якби жорно млинове повісили йому на шию і кинули його в море, ніж щоб він спокусив одного з малих цих.","Пильнуйте за собою. Якщо ж согрішить проти тебе брат твій, докори йому; і коли покається, прости йому;","і коли сім разів на день згрішить проти тебе і сім разів на день звернеться і скаже: каюсь, — прости йому.","І сказали апостоли Господу: додай нам віри.","Господь сказав: коли б ви мали віру, як зерно гірчичне, і сказали смоковниці цій: вирвись і пересадись у море, то вона послухала б вас.","Хто з вас, маючи раба, який оре або пасе, як тільки він повернеться з поля, скаже йому: іди мерщій та сідай до столу?","Навпаки, чи не скаже йому: приготуй мені повечеряти та, підперезавшись, прислуговуй мені, доки буду їсти і пити, а потім їж і пий сам?","Чи ж стане він дякувати рабові тому за те, що він виконав наказ? Не думаю.","Так і ви, коли виконаєте все, що вам наказувалося, кажіть: ми раби нікчемні; бо зробили тільки те, що повинні були зробити.","Йдучи до Єрусалима, Він проходив між Самарією та Галилеєю.","І коли входив Він в одне село, зустріли Його десять чоловік прокажених, які зупинилися віддалік.","І вони гучним голосом говорили: Ісусе, Наставнику, помилуй нас.","Побачивши їх, Він сказав їм: підіть покажіться священикам. І коли вони йшли, очистилися.","Один же з них, побачивши, що зцілився, повернувся, гучним голосом прославляючи Бога,","і припав лицем до ніг Його, віддаючи Йому хвалу; і це був самарянин.","Тоді Ісус сказав: чи не десять очистилися? Де ж дев’ять?","Чому вони не повернулися віддати славу Богові, тільки іноплемінник цей?","І сказав йому: встань, іди; віра твоя спасла тебе.","А як фарисеї запитали Його: коли прийде Царство Боже? — відповів їм: не прийде Царство Боже помітно,","і не скажуть: ось, воно тут, або: он там. Бо Царство Боже всередині вас є.","Сказав також ученикам: прийдуть дні, коли бажатимете бачити хоч один з днів Сина Людського, та не побачите.","І скажуть вам: ось тут, або: он там, — не ходіть і не ганяйтеся,","бо, як блискавка, блиснувши від одного краю неба, світить до другого краю неба, так буде Син Людський у день Свій.","Але насамперед належить Йому багато постраждати і бути відкинутим родом цим.","І як було в дні Ноя, так буде і в дні Сина Людського:","їли, пили, одружувалися і виходили заміж, аж до того дня, як увійшов Ной у ковчег, і прийшов потоп, і погубив усіх.","Так само, як було й у дні Лота: їли, пили, купували, продавали, саджали, будували;","а в той день, в який Лот вийшов з Содома, линули сірка палаюча й вогонь з небес і погубили усіх;","так буде і в той день, коли Син Людський явиться.","У той день, хто буде на покрівлі, а речі його в домі, нехай не злазить їх узяти; і хто буде на полі, також нехай не повертається назад.","Згадайте жінку Лотову.","Хто почне зберігати душу свою, той погубить її; а хто погубить її, той оживить її.","Кажу вам: у ту ніч будуть двоє на одній постелі: один візьметься, а другий залишиться.","Дві будуть молоти разом: одна візьметься, а друга залишиться.","Двоє будуть на полі: один візьметься, а другий залишиться.","На це сказали Йому: де, Господи? Він же сказав їм: де труп, там зберуться й орли."],"x":{"1":"50.18.6|51.9.42","3":"2.19.17|50.18.15|55.5.19","6":"50.17.20|50.21.21|51.11.23","10":"24.22.3|24.35.7|63.9.16","11":"53.4.4","12":"2.13.46","14":"2.14.2|50.8.4|51.1.44|52.5.14","23":"50.24.23|51.13.21","25":"50.16.21|50.17.22|50.20.18|51.8.31","26":"0.7.7|50.24.37|56.3.20","28":"0.19.14:24","32":"0.19.26|29.10.7","33":"50.10.39|51.8.35|52.9.24|53.12.25","35":"50.24.41","37":"50.24.28"}},{"v":["Сказав також їм і притчу про те, як треба завжди молитися і не занепадати духом,","кажучи: в одному місті був суддя, який Бога не боявся і людей не соромився.","В тому ж місті була одна вдова, і вона, приходячи до нього, говорила: захисти мене від суперника мого.","Але він довгий час не хотів. А потім сказав сам собі: хоч я і Бога не боюся і людей не соромлюсь,","але, оскільки ця вдова не дає мені спокою, захищу її, щоб вона не приходила більш докучати мені.","І сказав Господь: чуєте, що каже суддя неправедний?","Хіба Бог не захистить обранців Своїх, що волають до Нього день і ніч, чи баритиметься до них?","Кажу вам, що захистить їх скоро. Але Син Людський, коли прийде, чи знайде віру на землі?","Сказав також і до деяких, які були упевнені в собі, що вони праведні, а інших принижували, таку притчу.","Два чоловіки прийшли до храму помолитися: один фарисей, а другий митар.","Фарисей, ставши, так про себе молився: Боже! Дякую Тобі, що я не такий, як інші люди, грабіжники, неправедні, перелюбники, або як цей митар.","Пощу двічі на тиждень, даю десятину з усього, що надбаю.","А митар, стоячи віддалік, не смів навіть очей звести на небо; але, б’ючи себе в груди, говорив: Боже, будь милостивий до мене, грішного!","Кажу вам, що цей пішов до дому свого виправданий більше, ніж той: бо всякий, хто підноситься, принижений буде, а хто принижує себе, піднесеться.","Приносили ж до Нього і дітей, щоб Він доторкнувся до них; а ученики, бачачи те, боронили їм.","Але Ісус, підізвавши їх, сказав: пустіть дітей приходити до Мене і не забороняйте їм; бо таких є Царство Боже.","Істинно кажу вам: хто не прийме Царства Божого, як дитя, той не ввійде в нього.","І запитав Його один з начальників, кажучи: Учителю благий, що мені зробити, щоб успадкувати життя вічне?","Ісус сказав йому: чого ти називаєш Мене благим? Ніхто не благий, тільки один Бог.","Заповіді знаєш: не перелюбствуй, не вбивай, не кради, не лжесвідчи, шануй батька твого і матір твою.","Він же сказав: усе це я зберіг від юности моєї.","Почувши це, Ісус сказав: ще одного не вистачає тобі: все, що маєш, продай і роздай убогим, і матимеш скарб на небесах, і йди слідом за Мною.","Він же, почувши це, засмутився, бо був дуже багатий.","Ісус же, побачивши, що він засмутився, сказав: як важко тим, що мають багатство, увійти в Царство Боже!","Бо легше верблюдові пройти крізь вушко голки, ніж багатому ввійти до Царства Божого.","Ті, що чули, сказали: то хто ж може спастися?","Він же сказав: неможливе для людей — можливе для Бога.","Петро ж сказав: ось ми покинули все і пішли за Тобою.","Він сказав їм: істинно говорю вам, що немає нікого, хто покинув би дім, або батьків, або братів, або сестер, або жінку, або дітей заради Царства Божого","і не одержав би значно більше в цей час, а у віці майбутньому — життя вічне.","Взявши ж дванадцятьох учеників Своїх, сказав їм: ось ми йдемо до Єрусалима, і збудеться все, написане пророками про Сина Людського,","бо видадуть Його язичникам, і глузуватимуть з Нього, і скривдять Його, і обплюють Його.","І будуть бити, і уб’ють Його; та на третій день воскресне.","Але вони нічого з цього не зрозуміли; і були слова ці приховані для них, і вони не розуміли сказаного.","Коли ж наближався Він до Єрихона, один сліпий сидів край дороги і просив милостині.","Почувши, що повз нього проходить народ, запитав: що це таке?","Йому сказали, що Ісус Назарянин проходить.","Тоді він закричав: Ісусе, Сину Давидів, помилуй мене!","І ті, що йшли попереду, примушували його замовкнути; а він ще голосніше кричав: Сину Давидів, помилуй мене!","Зупинившись, Ісус звелів привести його до Себе. Коли той наблизився до Нього, спитав його:","чого ти хочеш від Мене? Він сказав: Господи, щоб мені прозріти!","Ісус сказав йому: прозри! Віра твоя спасла тебе.","І він умить прозрів і пішов за Ним, славлячи Бога; і всі люди, побачивши це, віддали хвалу Богові."],"x":{"1":"62.12.12|66.6.18|69.5.17","7":"25.9.19|52.11.9|76.6.10","9":"52.16.15","11":"31.58.3|76.3.17","14":"24.22.29|26.29.23|50.23.12|52.14.11","15":"50.19.13|51.10.13","16":"50.18.3|50.19.14|56.2.2|63.14.20","18":"50.19.16|51.10.17","20":"1.20.12-16|4.5.17","22":"71.6.18-19","24":"26.11.28|50.19.23|51.10.23|71.6.9-10","28":"50.19.27|51.10.28","31":"25.21.7|50.20.18|51.10.33","32":"31.53.7","35":"50.20.29|51.10.46"}},{"v":["Потім Ісус увійшов до Єрихона і проходив через нього.","І ось один муж на ім’я Закхей, він був старший над митарями і чоловік був багатий,","бажав бачити Ісуса, хто Він; але не міг за народом, бо був малий на зріст.","І, забігши наперед, виліз на смоковницю, щоб побачити Його, бо Він мав проходити біля неї.","Коли Ісус прийшов на те місце і, глянувши, побачив його, сказав йому: Закхею, злізь скоріше, бо сьогодні Мені належить бути в тебе в домі.","І він поспішно зліз і прийняв Його з радістю.","І всі, побачивши те, почали нарікати, що Він зайшов гостити до грішного чоловіка.","Закхей, вставши, сказав Господеві: Господи, половину добра мого я віддам убогим і, якщо кого скривдив чим, поверну вчетверо.","Ісус сказав йому: нині прийшло спасіння дому цьому, бо і він син Авраамів.","Прийшов бо Син Людський знайти і спасти, що загинуло.","Коли ж вони слухали це, розповів ще одну притчу; бо Він був недалеко від Єрусалима, і вони думали, що Царство Боже повинне скоро відкритися.","Отже, сказав: один чоловік високого роду вирушав у далеку країну, щоб прийняти собі царство і повернутися.","Покликавши десятьох рабів своїх, дав їм десять мин* і сказав їм: пустіть їх у діло, поки я повернусь.","Але громадяни ненавиділи його і відправили слідом за ним посланців, сказавши: ми не хочемо, щоб він царював над нами.","І коли він повернувся, прийнявши царство, то звелів покликати рабів тих, яким дав срібло, щоб довідатися, хто що придбав.","Прийшов перший і сказав: господарю, мина твоя принесла десять мин.","І сказав йому: гаразд, добрий рабе! За те, що ти у малому був вірний, візьми управління над десятьма містами.","Прийшов другий і сказав: господарю, мина твоя принесла п’ять мин.","Сказав і цьому: і ти будь над п’ятьма містами.","Прийшов ще один і сказав: господарю, ось твоя мина, яку я зберігав, загорнувши в хустину,","бо я боявся тебе, тому що ти чоловік жорстокий: береш, чого не клав, і жнеш, чого не сіяв.","Господар сказав йому: твоїми вустами суджу тебе, лукавий рабе! Ти знав, що я чоловік жорстокий: беру, чого не клав, і жну, чого не сіяв.","Чому ж ти не віддав срібла мого купцям, щоб я, повернувшись, узяв його з прибутком?","І сказав тим, що там стояли: візьміть у нього мину і дайте тому, що має десять мин.","І сказали йому: господарю, у нього є десять мин.","Кажу ж бо вам, що всякому, хто має, тому дасться; а хто не має, відбереться і те, що має.","А ворогів моїх, які не хотіли, щоб я царював над ними, приведіть сюди і повбивайте переді мною.","Сказавши це, Ісус пішов далі, підіймаючись до Єрусалима.","І коли наблизився до Виффагії та Вифанії, до гори, що зветься Елеонською, послав двох учеників Своїх","і сказав: підіть до села, що перед вами; увійшовши в нього, знайдете осля прив’язане, на яке ніхто з людей ніколи не сідав; відв’язавши його, приведіть.","А коли хто вас спитає: навіщо відв’язуєте? — скажіть йому так: Господь його потребує.","Посланці пішли і знайшли все так, як Він сказав їм.","Коли ж вони відв’язували осля, то господарі його сказали їм: навіщо відв’язуєте осля?","Вони відповіли: Господь його потребує.","І привели його до Ісуса, і, накинувши одяг свій на осля, посадили Ісуса.","І коли Він їхав, стелили одяг свій на дорозі.","А коли Він наближався вже до спуску з гори Елеонської, безліч учеників почали радісно хвалити Бога гучним голосом за всі чудеса, які вони бачили,","кажучи: благословен Цар, що гряде в ім’я Господнє! Мир на небесах і слава у вишніх!","І деякі фарисеї з народу сказали Йому: Учителю, заборони ученикам Твоїм.","Але Він сказав їм у відповідь: Я вам кажу, що коли вони замовкнуть, то каміння заголосить.","І коли, наблизившись, побачив місто, то заплакав над ним","і сказав: о, коли б зрозуміло ти хоч у цей твій день, що потрібне для твого миру! Але це сховано нині від очей твоїх.","Бо прийдуть на тебе дні, і вороги твої оточать тебе валом, і візьмуть в облогу тебе, і стиснуть тебе звідусіль.","І зруйнують тебе, і поб’ють дітей твоїх у тобі, і не залишать у тобі каменя на камені, бо ти не зрозуміло часу відвідин твоїх.","І ввійшовши у храм, почав виганяти тих, що в ньому продавали і купували,","кажучи їм: написано: дім Мій є дім молитви, а ви зробили його вертепом розбійників.","І навчав щодня в храмі. А первосвященики і книжники та старійшини народні шукали, як погубити Його,","і не знаходили, що б зробити з Ним, бо всі люди трималися Його і слухали Його."],"x":{"8":"1.22.1","10":"50.18.11","12":"50.25.14","17":"52.16.10","22":"24.15.6|50.12.37","26":"50.13.12|50.25.29|51.4.25|52.8.18","27":"50.22.7","29":"50.21.1|51.11.1","35":"50.21.7|51.11.7|53.12.14","38":"25.117.26|52.2.14|66.2.14","40":"45.2.11","43":"31.29.3|32.6.6|36.21.22|50.22.7|52.21.6","45":"50.21.12|51.11.15|53.2.15","46":"31.56.7|32.7.11|10.8.29"},"n":{"13":["Мина — фунт срібла."]}},{"v":["І сталося в один з тих днів, коли Він навчав народ у храмі і благовістив, прийшли первосвященики і книжники зі старійшинами.","І запитали Його: скажи нам, якою владою Ти це робиш, або хто дав Тобі цю владу?","Він сказав їм у відповідь: запитаю і Я вас про одне, скажіть Мені —","хрещення Іоанове було з небес чи від людей?","Вони ж, міркуючи між собою, говорили: коли скажемо, що з небес, то Він скаже: чому ж ви не повірили йому?","А коли скажемо, що від людей, то весь народ поб’є нас камінням, бо він упевнений, що Іоан є пророк.","І відповіли: не знаємо, звідки.","Ісус сказав їм: то і Я не скажу вам, якою владою це роблю.","І почав Він розповідати людям таку притчу: один чоловік насадив виноградник і віддав його виноградарям, та й відбув на довгий час.","І у певний час послав до виноградарів раба, щоб вони дали йому плодів з виноградника; але виноградарі, побивши його, відіслали ні з чим.","Ще послав другого раба; але вони і того, побивши і зневаживши, відіслали ні з чим.","І ще послав третього; але вони і того, поранивши, вигнали.","Тоді господар виноградника сказав: що мені робити? Пошлю сина мого улюбленого; може, побачивши його, посоромляться.","А виноградарі, побачивши його, міркували між собою, кажучи: це спадкоємець, ходім уб’ємо його, щоб спадщина була нашою.","І, вивівши його геть з виноградника, вбили. Що зробить з ними господар виноградника?","Прийде і погубить виноградарів тих, і віддасть виноградник іншим. Ті, що слухали це, сказали: нехай не буде так!","А Він, поглянувши на них, сказав: що значить оце написане: камінь, який відкинули будівничі, той самий став наріжним каменем?","Кожний, хто впаде на той камінь, розіб’ється; а на кого він упаде, того роздавить.","І шукали в цей час первосвященики і книжники, як накласти на Нього руки, та побоялися народу; бо зрозуміли, що про них сказав Він цю притчу.","І, слідкуючи за Ним, підіслали лукавих людей, які, вдаючи з себе праведних, зловили б Його на слові, щоб видати Його начальникам і владі правителя.","І вони запитали Його: Учителю, ми знаємо, що Ти правдиво говориш і навчаєш, і не дивишся на особу, але істинно на путь Божу наставляєш;","чи належить нам давати податок кесареві, чи ні?","Він же, зрозумівши їхнє лукавство, сказав їм: чого Мене спокушаєте?","Покажіть Мені динарій — чиє на ньому зображення і напис? Вони відповіли: кесареве.","Він сказав їм: отже, віддавайте кесареве кесареві, а Боже — Богові.","І не могли впіймати Його на слові перед народом і, здивувавшись відповіді Його, замовкли.","Тоді прийшли деякі з саддукеїв, які не визнають воскресіння, і запитали Його:","Учителю, Мойсей написав нам: коли у кого помре брат, що мав жінку, і помре бездітним, то нехай брат його візьме жінку його, відродить потомство братові своєму.","Отже, було сім братів, і перший взяв жінку і помер бездітним;","узяв ту жінку другий, і той помер бездітним;","узяв її третій, так само і всі семеро; і, не залишивши дітей, померли.","Після всіх померла і жінка.","Отже, у воскресінні, якому з них буде вона жінкою? Бо семеро мали її за дружину.","Ісус сказав їм у відповідь: сини віку цього женяться і виходять заміж;","а ті, що сподобилися досягти того віку і воскресіння з мертвих, не женяться і не виходять заміж.","І вмерти вже не можуть; бо вони рівні з ангелами і є сини Божі, ставши синами воскресіння.","А що мертві воскресають, і Мойсей показав при купині, коли Господа назвав Богом Авраама, і Богом Ісаака, і Богом Якова.","Бог же не є Бог мертвих, а живих. Бо в Нього всі живі.","На це деякі з книжників сказали: Учителю, Ти добре сказав.","І більше не насмілювалися запитувати Його ні про що. Він же сказав їм:","як це кажуть, що Христос є сином Давидовим,","А сам Давид говорить у книзі псалмів: сказав Господь Господеві моєму: сиди праворуч Мене,","доки покладу ворогів Твоїх підніжжям ніг Твоїх?","Отже, Давид називає Його Господом; як же Він син йому?","І коли увесь народ слухав, Він сказав ученикам Своїм:","стережіться книжників, які люблять ходити в довгому одязі і люблять, щоб їх вітали на народних зібраннях, мати перші місця в синагогах і перші місця на вечерях,","які з’їдають доми вдів і лицемірно довго моляться; вони приймуть тим більше осудження."],"x":{"1":"50.21.23|51.11.27","6":"50.14.5","9":"31.5.1|32.2.21|50.21.33|51.12.1","14":"75.1.2","15":"75.13.12","17":"25.117.22|31.28.16|50.21.42|51.12.10|54.4.11|56.2.6|62.9.33","20":"50.22.15|51.12.13","25":"50.17.27|50.22.21|62.13.7","27":"50.22.23|51.12.18|54.23.8","28":"4.25.5","37":"1.3.6:16|50.22.32|51.12.26","40":"50.22.42|51.12.35","42":"50.22.44","43":"25.109.1","46":"50.23.6|51.12.38-39|52.11.43"}},{"v":["Поглянувши, Він побачив багатіїв, які клали дари свої в скарбницю.","Побачив також і одну вбогу вдову, яка туди поклала дві лепти,","і сказав: істинно говорю вам, що ця вбога вдова більше за всіх поклала;","бо всі ті з надміру свого клали в дар Богові, а вона з убогости своєї поклала весь прожиток свій, що мала.","І коли деякі говорили про храм, що він прикрашений коштовним камінням і посудом, Він сказав:","надійдуть дні, в які з того, що ви тут бачите, не залишиться каменя на камені, який не зруйнується.","І запитали Його: Учителю, коли ж це буде? І яке знамення, коли це має статися?","Він сказав: стережіться, щоб вас не ввели в оману: бо багато прийде у Моє ім’я, кажучи, що це Я. І час цей наблизився. Отже, не йдіть слідом за ними.","Коли ж почуєте про війни та розрухи, не жахайтеся: бо цьому належить бути раніш; але то ще не кінець.","Тоді сказав їм: постане народ на народ і царство на царство.","Будуть великі землетруси місцями, і голод, і пошесті; і жахливі та великі знамення з неба будуть.","А перед усім тим накладуть на вас руки і гнатимуть вас, видаючи в синагоги і у в’язниці, і поведуть перед царів і правителів за ім’я Моє.","І буде це вам на свідчення.","Отже, покладіть собі у серцях ваших не загадувати наперед, що відповідати,","бо Я дам вам уста і премудрість, якій не зможуть противитися, ні суперечити всі супротивники ваші.","І видаватимуть вас і батьки, і брати, і родичі, і друзі, і декого з вас умертвлять;","і зненавидять вас усі за ім’я Моє.","Але й волосина з голови вашої не пропаде.","Терпінням вашим спасайте душі ваші.","Коли ж побачите Єрусалим, обложений військами, знайте, що наблизилося запустіння його.","Тоді, хто буде в Юдеї, нехай біжать у гори; і хто в місті — нехай виходять з нього, а хто в околицях — нехай не входять до нього,","бо це дні помсти, щоб справдилося все написане.","Горе вагітним і тим, що годують грудьми, в ті дні: бо буде велика біда на землі і гнів на народ цей.","І поляжуть від гострого меча, і відведені будуть у полон поміж усі народи; і Єрусалим буде потоптаний язичниками, аж доки не скінчаться часи язичників.","І будуть знамення на сонці, і місяці, і зірках, а на землі туга народів від раптового шуму морського і збурення.","Люди вмиратимуть від страху і чекання біди, що йде на всесвіт, бо сили небесні захитаються.","І тоді побачать Сина Людського, Який гряде на хмарах з силою і славою великою.","Коли ж це почне збуватися, тоді ви випростайтесь і підійміть голови ваші, бо наближається визволення ваше.","І сказав їм притчу: подивіться на смоковницю та на всі дерева:","коли вони розпускаються, то, дивлячись на це, ви знаєте, що вже близько літо.","Так і ви, коли побачите, що все те збувається, знайте, що близько Царство Боже.","Істинно кажу вам: не перейде рід цей, як усе це станеться.","Небо і земля перейдуть, слова ж Мої не перейдуть.","Зважайте на себе, щоб ваші серця не обтяжувались об’їданням та пияцтвом і житейськими турботами, і щоб день той не спостиг вас несподівано,","бо він, як сіть, прийде на усе, що живе на поверхні всієї землі.","Отже, пильнуйте повсякчас і моліться, щоб ви сподобились уникнути всього того, що має бути, і стати перед Сином Людським.","У день Він навчав у храмі; а на ніч виходив і перебував на горі, що зветься Елеонською.","І всі люди зранку приходили до Нього у храм, щоб послухати Його."],"x":{"1":"51.12.41","3":"64.8.12","5":"50.24.1|51.13.1","6":"10.9.7|52.19.44","8":"50.24.4|51.13.5|58.4.1|66.5.6|70.2.3","10":"31.19.2","12":"50.10.17|50.24.9|51.13.9|53.15.20","14":"52.12.11","15":"1.4.12|54.6.10","16":"43.7.6","19":"50.10.22","20":"37.9.27|50.24.15|51.13.14","22":"48.14.1","25":"31.13.10|36.32.7|39.2.31|39.3.15|40.5.20|40.8.9|46.1.15|50.24.29|51.13.24","27":"37.7.10|51.13.26","28":"62.8.23","33":"25.101.27|31.51.6|50.24.35","34":"56.4.7|62.13.13|69.5.6","35":"31.24.17","36":"50.24.42|50.25.13|51.13.33","37":"53.8.2"}},{"v":["Наближалося свято опрісноків, що зветься Пасхою.","І шукали первосвященики і книжники, як би погубити Його, але боялися народу.","Увійшов сатана в Іуду, званого Іскаріотом, що був з числа дванадцятьох,","і він пішов і говорив з первосвящениками та начальниками, як Його видати їм.","Вони зраділи і згодилися дати йому срібників.","І він обіцяв і шукав слушної нагоди, щоб видати їм Його без народу.","Настав же день опрісноків, коли належало заколювати пасхальне ягня.","І послав Ісус Петра та Іоана, сказавши: підіть, приготуйте нам їсти паску.","Вони ж сказали Йому: де хочеш, щоб ми приготували?","Він сказав їм: ось як увійдете в місто, зустріне вас чоловік, що нестиме глек води; ідіть слідом за ним до того дому, в який він увійде.","І скажіть господареві дому: Учитель говорить тобі: де кімната, в якій би Мені їсти паску з учениками Моїми?","І він покаже вам світлицю велику, прибрану; там приготуйте.","Вони пішли і знайшли, як сказав їм, і приготували паску.","І коли настав час, Він возліг, і дванадцять апостолів з Ним,","і сказав їм: дуже бажав Я цю паску їсти з вами, перш ніж зазнаю страждань.","Бо кажу вам, що не буду вже більш їсти її, доки вона не сповниться в Царстві Божому.","І, взявши чашу й воздавши хвалу, сказав: прийміть її та розділіть між собою.","Бо кажу вам, що не питиму від плоду виноградного, поки не прийде Царство Боже.","І, взявши хліб і воздавши хвалу, розломив і подав їм, кажучи: це є Тіло Моє, що за вас віддається; це чиніть на спомин про Мене.","Також і чашу після вечері, кажучи: ця чаша — Новий Завіт у Моїй Крові, що за вас проливається.","І ось рука того, хто зраджує Мене, зі Мною на трапезі.","Проте Син Людський іде, як призначено; але горе тій людині, що Його видає.","І вони почали питати один одного, хто з них є той, що хоче це зробити.","Сталася ж між ними і суперечка — хто з них має вважатися за більшого.","Він же сказав їм: царі народів панують над ними, і ті, хто володіє ними, доброчинцями звуться.","Ви ж не так: але більший між вами хай буде як менший, а старший — як слуга.","Бо хто більший: чи той, хто возлежить, чи той, хто услуговує? Чи не той, хто возлежить? А Я посеред вас, як слуга.","Але ви були зі Мною в напастях Моїх,","і Я заповідаю вам, як заповів Мені Отець Мій, Царство,","щоб ви їли і пили на трапезі Моїй у Царстві Моїм, і сядете на престолах судити дванадцять колін Ізраїлевих.","Сказав же Господь: Симоне, Симоне! Ось сатана просить вас, щоб сіяти, як пшеницю,","але Я молився за тебе, щоб не ослабла віра твоя; і ти колись, навернувшись, утверди братів твоїх.","Він відповів Йому: Господи, з Тобою я готовий і у в’язницю, і на смерть іти.","Він же промовив: кажу тобі, Петре, не заспіває півень сьогодні, як ти тричі зречешся, що не знаєш Мене.","І сказав їм: коли Я посилав вас без мішка, і без торби, і без взуття, чи мали ви в чому нестаток? Вони відповіли: ні в чому.","Тоді Він сказав їм: але тепер, хто має мішок, нехай візьме, також і торбу, а в кого немає, нехай продасть одяг свій і купить меч.","Бо кажу вам, що оце написане має здійснитися на Мені: і до злочинців прирівняли Його. Бо те, що про Мене, наближається до кінця.","Вони сказали: Господи, ось тут два мечі. Він сказав їм: досить!","І, вийшовши, пішов, за звичаєм, на гору Елеонську; за Ним пішли й ученики Його.","Прийшовши ж на місце, сказав їм: моліться, щоб не впасти в спокусу.","А Сам відійшов від них, як докинути каменем, і, ставши на коліна, молився,","говорячи: Отче, о, коли б Ти благоволив пронести чашу цю мимо Мене! А втім, не Моя воля, а Твоя нехай буде!","Явився ж Йому ангел з небес і укріплював Його.","І, перебуваючи в борінні, старанніше молився; і був піт Його як краплі крови, що падають на землю.","Вставши від молитви, Він прийшов до учеників і знайшов, що вони спали від смутку,","і сказав їм: чого спите? Встаньте і моліться, щоб не ввійшли у спокусу.","Коли Він ще говорив це, то ось з’явився народ, і званий Іудою, один з дванадцятьох, ішов попереду. І він приступив до Ісуса, щоб поцілувати Його. Бо такий знак він дав їм: Кого я поцілую, Той і є.","Ісус же сказав йому: Іудо! То ти поцілунком Сина Людського видаєш?!","Ті ж, що з Ним були, побачивши, що відбувається, сказали Йому: Господи, чи не вдарити нам мечем?","І один з них вдарив слугу первосвященика і відсік йому праве вухо.","Озвався тоді Ісус і сказав: облиште, досить! І, доторкнувшись до його вуха, зцілив його.","Сказав Ісус тим, що прийшли по Нього, — первосвященикам і начальникам храму та старійшинам: мов на розбійника, вийшли ви з мечами й киями, щоб узяти Мене!","Щодня бував Я з вами у храмі, і ви не здіймали рук на Мене; але тепер ваша година і влада темряви.","Узявши Його, повели і привели Його у двір первосвященика. Петро ж ішов слідом віддалік.","Коли вони розклали вогонь посеред двору і сіли разом, сів і Петро між ними.","Одна служниця побачила його, що він сидить при світлі, і, придивившись до нього, сказала: і цей був з Ним.","Але він відрікся від Нього, сказавши: жінко, я не знаю Його!","Невдовзі другий, побачивши його, сказав: і ти з них. Петро ж сказав цьому чоловікові: ні!","Минула ще приблизно година, й хтось інший твердив, говорячи: воістину і цей був з Ним, бо і він галилеянин.","Але Петро сказав тому чоловікові: не знаю, що ти говориш. І зараз же, коли він ще говорив, заспівав півень.","І, обернувшись, Господь глянув на Петра, і Петро згадав слово Господнє, як Він сказав йому: перш ніж півень заспіває, тричі зречешся Мене.","І, вийшовши геть, плакав гірко.","Люди, які тримали Ісуса, глумилися з Нього і били Його.","І, закривши Його, били Його по обличчю і питали Його: проречи, хто Тебе вдарив?","І багато іншої хули говорили на Нього.","А коли настав день, зібралися старійшини народу, первосвященики і книжники, та повели Його у свій синедріон","і питали: чи Ти Христос? Скажи нам. Він відповів їм: якщо Я скажу вам, не повірите.","Коли ж Я запитаю вас, не відповісте Мені і не відпустите.","Віднині Син Людський сяде праворуч сили Божої.","І сказали всі: чи Ти Син Божий? Він же відповів: ви говорите, що Я.","Вони ж сказали: якого ще свідчення нам треба? Самі бо чули з уст Його."],"x":{"1":"50.26.2|51.14.1-2","3":"50.26.14","7":"4.16.1|50.26.17|51.14.12","14":"50.26.20|51.14.18|53.13.12","16":"54.10.41","19":"50.26.26|51.14.22|63.11.24","21":"25.40.10|50.26.22-23","22":"54.2.23|54.4.28","27":"67.2.7","30":"50.19.28|63.6.2|76.3.21|76.20.4","31":"56.5.8","32":"50.16.18|53.17.15","34":"50.26.34|51.14.30|53.13.38","35":"50.10.9-10|51.6.8|52.9.3|52.10.4","37":"31.53.12|51.15.28","39":"50.26.36|51.14.32|53.18.1","40":"50.26.41|51.14.38","47":"50.26.48|51.14.43|53.18.3","54":"50.26.57|51.14.53|53.18.24","61":"50.26.34|51.14.30:72|53.13.38","63":"50.26.67|51.14.65","66":"25.2.2|50.27.2|51.15.1|53.18.28","69":"25.109.1|37.7.13|50.26.64|51.14.62|53.6.62"}},{"v":["І піднялася вся громада їхня, і повели Його до Пилата.","І почали звинувачувати Його, кажучи: ми знайшли Цього, Який розбещує народ наш і забороняє давати податок кесареві, називаючи Себе Христом Царем.","Пилат запитав Його: Ти Цар Юдейський? Він же сказав йому у відповідь: ти кажеш.","Пилат сказав первосвященикам і народові: ніякої провини я не знаходжу в Чоловікові Цьому.","Але вони наполягали, кажучи, що Він розбещує народ, навчаючи по всій Юдеї, починаючи від Галилеї і аж до цього місця.","Пилат, почувши про Галилею, запитав: хіба Він галилеянин?","І, довідавшись, що Він з области Іродової, послав Його до Ірода, який у ці дні теж був у Єрусалимі.","Ірод же, побачивши Ісуса, дуже зрадів, бо давно вже хотів Його бачити, тому що багато чув про Нього і сподівався побачити від Нього яке-небудь знамення.","І ставив Йому багато запитань, але Він нічого не відповідав йому.","Первосвященики ж і книжники стояли і наполегливо звинувачували Його.","Але Ірод зі своїми воїнами, зневаживши Його і познущавшись з Нього, вдягнув Його у світлий одяг і повернув Його до Пилата.","І стали від того дня Ірод і Пилат друзями, бо раніше мали ворожнечу між собою.","Пилат же, скликавши первосвящеників і начальників та народ,","сказав їм: ви привели до мене Чоловіка Цього, який ніби розбещує народ; і ось я перед вами допитав і не знайшов Чоловіка Цього винним ні в чому з того, в чому ви звинувачуєте Його.","Й Ірод теж, бо я послав Його до нього, і нічого, вартого смерти, Він не вчинив.","Отже, покаравши Його, відпущу.","А йому і треба було заради свята відпустити їм одного в’язня.","Але весь народ почав кричати: візьми Цього, відпусти ж нам Варавву!","А той за якийсь вчинений у місті бунт і вбивство був посаджений до в’язниці.","Пилат знову підвищив голос, бажаючи відпустити Ісуса.","Але вони кричали: розіпни, розіпни Його!","Він утретє сказав їм: яке ж зло Він учинив? Я нічого, вартого смерти, не знайшов у Ньому; отже, покаравши Його, відпущу.","Але вони продовжували з великим криком вимагати, щоб Він був розп’ятий; і перемогли крики їхні і первосвящеників.","І Пилат присудив, щоб було за проханням їхнім.","І відпустив їм ув’язненого за бунт і вбивство, якого вони просили; Ісуса ж віддав на їхню волю.","І коли повели Його, то, затримавши якогось Симона киринеянина, що йшов з поля, поклали на нього хрест, щоб ніс за Ісусом.","І йшло за Ним дуже багато народу і жінок, які плакали і ридали за Ним.","Ісус же, обернувшись до них, сказав: дочки єрусалимські! Не плачте за Мною, а плачте за собою і за дітьми вашими.","Бо ось надходять дні, коли скажуть: блаженні неплідні, і утроби, які не родили, і груди, які не годували!","Тоді почнуть говорити горам: упадіть на нас! І пагорбам: покрийте нас!","Бо коли із зеленим деревом таке роблять, то що ж буде з сухим?","Вели і двох злочинців з Ним, щоб убити.","І коли прийшли на місце, що зветься Лобним, тут розп’яли Його і злочинців, одного з правого, а другого з лівого боку.","Ісус же говорив: Отче, прости їм, бо не відають, що чинять. А ті, що ділили одяг Його, кидали жереб.","І стояли люди і дивилися. Насміхалися ж разом з ними і начальники, кажучи: інших спасав; нехай спасе Себе, якщо Він Христос, Божий обранець.","Глузували з Нього і воїни, підходячи та підносячи Йому оцет,","і казали: якщо Ти Цар Юдейський, спасися Сам.","І був над Ним напис, написаний письмом грецьким, римським і єврейським: «Цей є Цар Юдейський».","Один з розіп’ятих злочинців хулив Його, говорячи: якщо Ти Христос, спаси Себе і нас.","Озвався і другий, і докоряв тому, і казав: чи ти не боїшся Бога, коли й сам на те саме засуджений?","І ми засуджені справедливо, бо достойне за діла наші одержали; а Він нічого лихого не вчинив.","І сказав Ісусові: пом’яни мене, Господи, коли прийдеш у Царство Твоє!","І сказав йому Ісус: істинно кажу тобі: сьогодні ж будеш зі Мною в раю.","Було ж близько шостої години*, і настала темрява по всій землі аж до години дев’ятої.","І сонце затьмарилось, і завіса в храмі роздерлася посередині.","Скрикнувши гучним голосом, Ісус сказав: Отче, у Твої руки віддаю дух Мій. І, сказавши це, віддав дух.","Сотник же, побачивши, що сталося, прославив Бога і сказав: воістину Чоловік Цей був праведний.","І весь народ, який зійшовся на це видовище, побачивши, що сталося, повертався, б’ючи себе в груди.","Всі ж, хто знав Його, і жінки, які прийшли з Ним з Галилеї, стояли віддалік і дивилися на це.","І ось один чоловік на ім’я Йосиф, що був радником*, чоловік благий і праведний,","який не брав участи у раді і справі їхній, з Аримафеї, міста юдейського, який і сам сподівався Царства Божого,","прийшов до Пилата і просив тіло Ісусове.","І, знявши Його, обгорнув плащаницею і поклав Його у гробі, висіченому в скелі, де ще ніхто ніколи не був покладений.","День той був п’ятниця, і надходила субота.","Слідом же йшли жінки, які прийшли з Ісусом з Галилеї, і бачили гріб, і як покладено було тіло Його.","Повернувшися, вони наготували пахощі та миро і в суботу нічого не робили, за заповіддю."],"x":{"1":"50.27.2|51.15.1|53.18.28","2":"50.22.21","3":"50.27.11|51.15.2|53.18.33|71.6.13|76.1.5","8":"52.9.9","11":"31.53.3","14":"50.27.23|51.15.14|53.18.38|53.19.4","18":"50.27.20|51.15.11|53.18.40|54.3.14","30":"31.2.19|38.10.8|76.6.15|76.9.6","33":"50.27.33|51.15.22|53.19.17","34":"25.21.19|50.5.44|50.27.35|51.15.24|53.19.23","42":"50.16.28","44":"40.8.9","46":"25.30.6","50":"50.27.57|51.15.43|53.19.38","56":"1.20.10"},"n":{"44":["Тобто близько 12-ї години дня."],"50":["Член синедріону."]}},{"v":["Першого ж дня після суботи, дуже рано, несучи наготовані пахощі, вони прийшли до гробу, і разом з ними деякі інші.","Знайшли ж, що камінь був відвалений від гробу.","І, увійшовши, не знайшли тіла Господа Ісуса.","Коли ж вони не могли зрозуміти цього, ось два мужі стали перед ними в одежах блискучих.","Налякалися вони і схилилися обличчям до землі, а ті сказали їм: чого шукаєте Живого між мертвими?","Нема Його тут, Він воскрес. Згадайте, як Він говорив вам, коли був ще в Галилеї,","кажучи, що Синові Людському належить бути виданому до рук людей-грішників, і бути розп’ятим, і на третій день воскреснути.","І згадали слова Його.","І, повернувшись від гробу, сповістили про все те одинадцятьох і всіх інших.","То були Магдалина Марія, й Іоанна, і Марія Яковова, та інші з ними, які сказали про це апостолам.","І здалися їм слова їхні неправдивими, і вони не повірили їм.","Петро ж, уставши, побіг до гробу і, нахилившись, побачив самі тільки ризи, що лежали, і пішов назад, дивуючися з того, що сталося.","Того ж дня двоє з них йшли в село, що було стадій* за шістдесят від Єрусалима і звалося Еммаус.","І розмовляли між собою про всі ці події.","І коли вони розмовляли і міркували між собою, Сам Ісус, наблизившись, пішов з ними.","Але очі їхні були стримані, так що вони не впізнали Його.","Він же сказав до них: про що ви сперечаєтесь між собою, ідучи, і чим ви засмучені?","Один з них, на ім’я Клеопа, сказав Йому у відповідь: невже Ти, один з тих, що прийшли до Єрусалима, не знаєш, що сталося в ньому цими днями?","І сказав їм: що саме? Вони відповіли Йому: про Ісуса Назарянина, Який був мужем-пророком, сильним ділом і словом перед Богом і всіма людьми.","Як видали Його первосвященики і начальники наші для засудження на смерть і розіп’яли Його.","Ми ж сподівалися, що Він є Той, Хто має визволити Ізраїль, до того ж сьогодні вже третій день, як усе це сталося.","Та ще й налякали нас деякі жінки з наших, які вранці були біля гробу,","і не знайшли тіла Його, і, прийшовши, розповідали, що вони бачили і явлення ангелів, які говорять, що Він живий.","І пішли деякі з наших до гробу, і знайшли так, як жінки говорили, а Самого ж не бачили.","Тоді Він сказав їм: о нерозумні і мляві серцем, щоб вірувати в усе, про що говорили пророки!","Чи не так же належало постраждати Христу й увійти в славу Свою?","І, почавши від Мойсея і від усіх пророків, пояснював їм сказане про Нього у всьому Писанні.","І наблизились вони до того села, куди йшли; і Він робив вигляд, що хоче йти далі.","А вони затримували Його, кажучи: залишся з нами, бо вже вечоріє, і день закінчується. І Він увійшов і залишився з ними.","І коли Він возлежав з ними, то взяв хліб, благословив, переломив і подав їм.","У них же відкрилися очі, і вони впізнали Його. Але Він став невидимим для них.","І вони казали один одному: чи ж не палало в нас серце наше, коли Він говорив нам у дорозі і коли пояснював нам Писання?","І, вставши тієї ж години, повернулися до Єрусалима і знайшли разом одинадцятьох і тих, що були з ними,","які говорили, що Господь воістину воскрес і явився Симонові.","І вони розповіли, що було в дорозі, і як вони Його впізнали у переломленні хліба.","Коли вони про це говорили, Сам Ісус став посеред них і сказав їм: мир вам.","Вони схвилювались і злякалися, гадаючи, що бачать духа.","Але Він сказав їм: чого хвилюєтесь, чому такі думки входять до сердець ваших?","Погляньте на руки Мої і на ноги Мої; це Я Сам. Доторкніться до Мене і роздивіться; бо дух тіла і кісток не має, як бачите у Мене.","І, сказавши це, показав їм руки і ноги.","Коли ж вони від радости ще не вірили і дивувалися, Він сказав їм: чи маєте тут якусь їжу?","Вони подали Йому частину печеної риби і стільниковий мед.","І, взявши, їв перед ними.","І сказав їм: ось ті слова, що Я говорив вам, коли ще був з вами, як належить справдитися всьому, написаному про Мене в законі Мойсеєвому і у пророків та в псалмах.","Тоді розкрив їм розум до розуміння Писання.","І сказав їм: так написано, і так належало постраждати Христу, і воскреснути з мертвих на третій день,","і щоб проповідувалося в ім’я Його покаяння і відпущення гріхів між усіма народами, починаючи від Єрусалима.","Ви ж є свідками цього.","І ось Я посилаю обітницю Отця Мого на вас; ви ж лишайтесь у місті Єрусалимі, доки не сповнитеся силою з неба.","І вивів їх до Вифанії, і, піднявши руки Свої, благословив їх.","І коли Він благословляв їх, почав віддалятися від них і вознісся на небо.","Вони, поклонившись Йому, повернулися до Єрусалима з великою радістю.","І перебували завжди в храмі, прославляючи і благословляючи Бога. Амінь."],"x":{"1":"50.28.1|51.16.1|53.20.1","6":"50.17.22","7":"51.9.31|52.9.22","12":"53.20.6","13":"51.16.12","19":"50.21.11|52.7.16|53.3.2|53.6.14|54.2.22","21":"52.2.25|54.26.6","25":"0.3.15|0.22.18|0.49.10-11|3.21.9|25.21.7|25.68.10|25.21.27|31.50.6|31.53.3","26":"25.15.8-10|31.40.10|32.23.5|32.33.15|36.34.23|36.37.24|37.9.24|43.7.20","36":"51.16.14|53.20.19|54.13.31|63.15.5","44":"50.16.21","45":"53.5.39","46":"31.53.4|52.24.27","49":"53.14.16|53.15.26|54.1.4:8","51":"51.16.19|54.1.9"},"n":{"13":["Стадія — близько 185 м."]}}];
export default C;
